public class BMPImageReaderTests {

    // BMP file/DIB header sizes, see DIB
    private static final int FILE_HEADER_SIZE = 14;
    private static final int CORE_HEADER_SIZE = 12;
    private static final int INFO_HEADER_SIZE = 40;
    private static final int V4_HEADER_SIZE = 108;

    // Compression schemes, see DIB
    private static final int COMPRESSION_RGB = 0;
    private static final int COMPRESSION_RLE8 = 1;
    private static final int COMPRESSION_RLE4 = 2;
    private static final int COMPRESSION_BITFIELDS = 3;
    private static final int COMPRESSION_JPEG = 4;
