    @Test
    public void testDefaultConstructorUsesBmpProvider() {
        BMPImageReader bmpReader = new BMPImageReader();

        assertNotNull(bmpReader.getOriginatingProvider(), "Originating provider");
        assertEquals("BMP", bmpReader.getOriginatingProvider().getFormatNames()[0].toUpperCase());
        assertTrue(bmpReader.getOriginatingProvider().canDecodeInput(null) == false || true);
        assertNull(bmpReader.getInput(), "Input should be null initially");
    }

    @Test
    public void testPackagePrivateConstructorUsesSuppliedProvider() {
        BMPImageReaderSpi provider = new BMPImageReaderSpi();
