    }

    @Test
    public void testMethodsRequireInput() {
        BMPImageReader bmpReader = new BMPImageReader();

        assertThrows(IllegalStateException.class, () -> bmpReader.getNumImages(true));
        assertThrows(IllegalStateException.class, () -> bmpReader.getWidth(0));
        assertThrows(IllegalStateException.class, () -> bmpReader.getHeight(0));
        assertThrows(IllegalStateException.class, () -> bmpReader.getRawImageType(0));
        assertThrows(IllegalStateException.class, () -> bmpReader.read(0, null));
    }

    @Test
    public void testSetInputResetsHeaderState() throws IOException {
        setInput(new Bmp(3, 2, 24).pixels(rgb24(3, 2, false, new int[][]{
                {0xFF0000, 0x00FF00, 0x0000FF},
                {0xFFFFFF, 0x000000, 0x808080}
        })).build());

        assertEquals(3, reader.getWidth(0));
        assertEquals(2, reader.getHeight(0));

        // Set a new input with different dimensions, the cached header must be discarded
        ImageInputStream second = new ByteArrayImageInputStream(new Bmp(5, 7, 24)
                .pixels(new byte[((24 * 5 + 31) / 32) * 4 * 7]).build());
        try {
            reader.setInput(second);
            assertEquals(5, reader.getWidth(0));
            assertEquals(7, reader.getHeight(0));
        }
        finally {
            second.close();
        }
    }

    @Test
    public void testReadIsRepeatable() throws IOException {
        setInput(new Bmp(2, 2, 24).pixels(rgb24(2, 2, false, new int[][]{
