                {0x0000FF, 0xFFFFFF}
        })).build());

        BufferedImage first = reader.read(0, null);
        BufferedImage second = reader.read(0, null);

        assertNotSame(first, second);
        assertEquals(first.getRGB(0, 0), second.getRGB(0, 0));
        assertEquals(first.getRGB(1, 1), second.getRGB(1, 1));
    }

