    public void testReadJpegCompressedBmpDelegatesToJpegReader() throws IOException {
        byte[] jpeg = writeImage("jpeg", 4, 3);

        byte[] container = new Bmp(4, 3, 0).compression(COMPRESSION_JPEG)
                .pixels(jpeg).build();

