                0x04, 0x01,                                     // Bottom file row: four pixels of index 1
                0x00, 0x04, 0x02, 0x02, 0x03, 0x03             // Top file row: absolute mode, 2, 2, 3, 3
        };

        setInput(new Bmp(4, 2, 8).compression(COMPRESSION_RLE8).palette(PALETTE)
                .pixels(rle).build());

        BufferedImage image = reader.read(0, null);

        assertEquals(4, image.getWidth());
        assertEquals(2, image.getHeight());
        // File row 0 is the bottom row of a bottom-up image
        assertEquals(PALETTE[1], image.getRGB(0, 1));
        assertEquals(PALETTE[1], image.getRGB(3, 1));
        assertEquals(PALETTE[2], image.getRGB(0, 0));
        assertEquals(PALETTE[2], image.getRGB(1, 0));
        assertEquals(PALETTE[3], image.getRGB(2, 0));
        assertEquals(PALETTE[3], image.getRGB(3, 0));
    }

    @Test
    public void testReadRle4() throws IOException {
        byte[] rle = {
                0x04, 0x12, 0x00, 0x00, // Bottom file row: 1, 2, 1, 2 then end of line
                0x04, 0x33, 0x00, 0x00  // Top file row: 3, 3, 3, 3 then end of line
        };

        setInput(new Bmp(4, 2, 4).compression(COMPRESSION_RLE4).palette(PALETTE)
                .pixels(rle).build());

        BufferedImage image = reader.read(0, null);

        assertEquals(PALETTE[1], image.getRGB(0, 1));
        assertEquals(PALETTE[2], image.getRGB(1, 1));
        assertEquals(PALETTE[1], image.getRGB(2, 1));
        assertEquals(PALETTE[2], image.getRGB(3, 1));

        for (int x = 0; x < 4; x++) {
            assertEquals(PALETTE[3], image.getRGB(x, 0), "Pixel x=" + x + ", y=0");
        }
    }

