    @Test
    public void testAllBmpsuiteGoodFilesAreReadable() throws Exception {
        File[] files = resourceDir("/bmpsuite/g");
        assertTrue(files.length > 0, "Missing BMP Suite 'good' files");

        for (File file : files) {
            byte[] data = readFile(file);
            ImageInputStream stream = new ByteArrayImageInputStream(data);
            BMPImageReader bmpReader = new BMPImageReader();
            try {
                bmpReader.setInput(stream);

                int width = bmpReader.getWidth(0);
                int height = bmpReader.getHeight(0);
                assertTrue(width > 0 && height > 0, file.getName());

                BufferedImage image = bmpReader.read(0, null);

                assertNotNull(image, file.getName());
                assertEquals(width, image.getWidth(), file.getName());
                assertEquals(height, image.getHeight(), file.getName());
            }
            finally {
                bmpReader.dispose();
                stream.close();
            }
        }
    }

    @Test
    public void testRealWorldPaletteFileMetadata() throws Exception {
        setInput(readFile(new File(resourceDir("/bmpsuite/g"), "pal8.bmp")));

        IIOMetadata metadata = reader.getImageMetadata(0);
        IIOMetadataNode root = (IIOMetadataNode) metadata.getAsTree("javax_imageio_bmp_1.0");

        assertEquals("8", nodeValue(root, "BitsPerPixel"));
        assertEquals("127", nodeValue(root, "Width"));
        assertEquals("64", nodeValue(root, "Height"));

        IIOMetadataNode palette = (IIOMetadataNode) root.getElementsByTagName("Palette").item(0);
        assertNotNull(palette, "Expected a Palette node");
        assertEquals(256, palette.getElementsByTagName("PaletteEntry").getLength());
    }

    @Test
    public void testHugeDimensionsAreRejectedBeforeAllocation() throws Exception {
        // BMP Suite "bad" file, declares a 30000x30000 image in a tiny file
        setInput(readFile(new File(resourceDir("/bmpsuite/b"), "reallybig.bmp")));

        IIOException exception = assertThrows(IIOException.class, () -> reader.read(0, null));

        assertTrue(exception.getMessage().contains("exceeding"),
                "Unexpected message: " + exception.getMessage());
    }

    @Test
    public void testTruncatedFileThrowsIOException() throws Exception {
        setInput(readFile(new File(resourceDir("/bmpsuite/b"), "shortfile.bmp")));

        assertThrows(IOException.class, () -> reader.read(0, null));
    }

