    public void testBmpsuiteBadBitCountFileIsRejected() throws Exception {
        setInput(readFile(new File(resourceDir("/bmpsuite/b"), "badbitcount.bmp")));

        IIOException exception = assertThrows(IIOException.class, () -> reader.getRawImageType(0));

        assertTrue(exception.getMessage().contains("Unsupported bit count"),
                "Unexpected message: " + exception.getMessage());
    }

    @Test
    public void testBmpsuiteBadPlanesFileIsRejected() throws Exception {
