    setInput(new Bmp(3, 2, 16).pixels(leRows(3, 2, 2, false, new int[][]{
            {0x7C00, 0x03E0, 0x001F},
            {0x7FFF, 0x0000, 0x7C00}
    }, rowSize(3, 16))).build());

    BufferedImage image = reader.read(0, null);

    assertEquals(3, image.getWidth());
    assertEquals(0xFFFF0000, image.getRGB(0, 0));
    assertEquals(0xFF00FF00, image.getRGB(1, 0));
    assertEquals(0xFF0000FF, image.getRGB(2, 0));
    assertEquals(0xFFFFFFFF, image.getRGB(0, 1));
    assertEquals(0xFF000000, image.getRGB(1, 1));
    assertEquals(0xFFFF0000, image.getRGB(2, 1));
}

