import static org.junit.jupiter.api.Assertions.assertNotNull;
import static org.junit.jupiter.api.Assertions.assertNull;
import static org.junit.jupiter.api.Assertions.assertNotSame;
import static org.junit.jupiter.api.Assertions.assertSame;
import static org.junit.jupiter.api.Assertions.assertThrows;
import static org.junit.jupiter.api.Assertions.assertTrue;

/**
 * Tests for {@link BMPImageReader}.
 * <p>
 * The tests build small BMP files in memory, so that both the file structure
 * (bit depth, compression, headers, palette) and the decoded pixel values are
 * fully known and deterministic.
 * </p>
 */
public class BMPImageReaderTests {

    // BMP file/DIB header sizes, see DIB
    private static final int FILE_HEADER_SIZE = 14;
    private static final int CORE_HEADER_SIZE = 12;
    private static final int INFO_HEADER_SIZE = 40;
    private static final int V4_HEADER_SIZE = 108;

    // Compression schemes, see DIB
    private static final int COMPRESSION_RGB = 0;
    private static final int COMPRESSION_RLE8 = 1;
    private static final int COMPRESSION_RLE4 = 2;
    private static final int COMPRESSION_BITFIELDS = 3;
    private static final int COMPRESSION_JPEG = 4;
    private static final int COMPRESSION_PNG = 5;
    private static final int COMPRESSION_ALPHA_BITFIELDS = 6;

    // Palette used by most palette based tests
    private static final int[] PALETTE = {
            0xFFFF0000, // 0: red
            0xFF00FF00, // 1: green
            0xFF0000FF, // 2: blue
            0xFFFFFFFF  // 3: white
    };

    private BMPImageReader reader;
    private ImageInputStream input;

    @AfterEach
    void tearDown() throws IOException {
        if (reader != null) {
            reader.dispose();
            reader = null;
        }
        if (input != null) {
            input.close();
            input = null;
        }
    }

    private void setInput(final byte[] bmp) throws IOException {
        reader = new BMPImageReader();
        input = new ByteArrayImageInputStream(bmp);
        reader.setInput(input);
    }

    // ----------------------------------------------------------------------
    // Construction and provider/state contract
    // ----------------------------------------------------------------------

    @Test
    public void testDefaultConstructorUsesBmpProvider() {
        BMPImageReader bmpReader = new BMPImageReader();

// ----------------------------------------------------------------------
// Header parsing and error handling
// ----------------------------------------------------------------------

@Test
public void testGetNumImagesReturnsOne() throws IOException {
    setInput(new Bmp(1, 1, 24).pixels(rgb24(1, 1, false, new int[][]{{0x123456}})).build());

    assertEquals(1, reader.getNumImages(true));
    assertEquals(1, reader.getNumImages(false));
}

@Test
public void testDimensionsComeFromHeader() throws IOException {
    setInput(new Bmp(11, 7, 24).pixels(new byte[((24 * 11 + 31) / 32) * 4 * 7]).build());

    assertEquals(11, reader.getWidth(0));
    assertEquals(7, reader.getHeight(0));
}

@Test
public void testTopDownImageHasPositiveHeight() throws IOException {
    setInput(new Bmp(3, 4, 24).topDown()
            .pixels(new byte[((24 * 3 + 31) / 32) * 4 * 4]).build());

    assertEquals(3, reader.getWidth(0));
    assertEquals(4, reader.getHeight(0), "Top-down (negative header height) should report absolute height");
}

@Test
public void testIndexOutOfBounds() throws IOException {
    setInput(new Bmp(1, 1, 24).pixels(rgb24(1, 1, false, new int[][]{{0}})).build());

    assertThrows(IndexOutOfBoundsException.class, () -> reader.getWidth(-1));
    assertThrows(IndexOutOfBoundsException.class, () -> reader.getHeight(-1));
    assertThrows(IndexOutOfBoundsException.class, () -> reader.getWidth(1));
    assertThrows(IndexOutOfBoundsException.class, () -> reader.read(3, null));
    assertThrows(IndexOutOfBoundsException.class, () -> reader.getRawImageType(1));
}

@Test
public void testNotABmpThrows() {
    byte[] notBmp = new byte[64];
    notBmp[0] = 'X';
    notBmp[1] = 'X';

    IIOException exception = assertThrows(IIOException.class, () -> {
        setInput(notBmp);
        reader.getNumImages(true);
    });

    assertEquals("Not a BMP", exception.getMessage());
}

@Test
public void testTruncatedHeaderThrowsIOException() {
    // Valid magic, but the stream ends inside the file header
    byte[] truncated = new byte[10];
    truncated[0] = (byte) (char) (0x42); // B
    truncated[1] = (byte) (char) (0x4D); // M

    assertThrows(IOException.class, () -> {
        setInput(truncated);
        reader.getNumImages(true);
    });

    assertThrows(IOException.class, () -> {
        setInput(new byte[8]);
        reader.getNumImages(true);
    });
}

@Test
public void testUnknownDibHeaderSizeThrows() {
    byte[] truncated = new Bmp(1, 1, 24).headerSize(33)
            .pixels(rgb24(1, 1, false, new int[][]{{0}})).build();

    IIOException exception = assertThrows(IIOException.class, () -> {
        setInput(truncated);
        reader.getNumImages(true);
    });

    assertTrue(exception.getMessage().contains("Unknown Bitmap Information Header"),
            "Unexpected message: " + exception.getMessage());
}

@Test
public void testPixelOffsetBeforeEndOfHeaderThrows() {
    byte[] invalidOffset = new Bmp(1, 1, 24).pixelOffsetDelta(-30)
            .pixels(rgb24(1, 1, false, new int[][]{{0}})).build();

    IIOException exception = assertThrows(IIOException.class, () -> {
        setInput(invalidOffset);
        reader.getWidth(0);
    });

    assertTrue(exception.getMessage().startsWith("Invalid pixel offset"),
            "Unexpected message: " + exception.getMessage());
}

@Test
public void testMultiplePlanesNotSupported() throws IOException {
    setInput(new Bmp(2, 2, 24).planes(2).pixels(new byte[((24 * 2 + 31) / 32) * 4 * 2]).build());

    // Dimensions are read fine
    assertEquals(2, reader.getWidth(0));

    IIOException exception = assertThrows(IIOException.class, () -> reader.getRawImageType(0));
    assertEquals("Multiple planes not supported", exception.getMessage());

    assertThrows(IIOException.class, () -> reader.read(0, null));
}

@Test
public void testUnsupportedBitCountThrows() {
    byte[] unsupported = new Bmp(2, 2, 3).pixels(new byte[16]).build();

    IIOException exception = assertThrows(IIOException.class, () -> {
        setInput(unsupported);
        reader.getRawImageType(0);
    });

    assertTrue(exception.getMessage().contains("Unsupported bit count: 3"),
            "Unexpected message: " + exception.getMessage());
}

@Test
public void testCompressed24BitIsUnsupported() {
    byte[] compressed = new Bmp(2, 2, 24).compression(COMPRESSION_RLE4)
            .pixels(new byte[16]).build();

    IIOException exception = assertThrows(IIOException.class, () -> {
        setInput(compressed);
        reader.read(0, null);
    });

    assertTrue(exception.getMessage().contains("Unsupported compression for RGB: 2"),
            "Unexpected message: " + exception.getMessage());
}

@Test
public void testUnsupportedCompressionThrowsOnRead() {
    byte[] unknownCompression = new Bmp(2, 2, 8).compression(11).palette(PALETTE)
            .pixels(new byte[8]).build();

    IIOException exception = assertThrows(IIOException.class, () -> {
        setInput(unknownCompression);
        reader.read(0, null);
    });

    assertTrue(exception.getMessage().contains("Unsupported compression: 11"),
            "Unexpected message: " + exception.getMessage());
}

@Test
public void testRle8RequiresEightBit() {
    byte[] mismatch = new Bmp(4, 2, 4).compression(COMPRESSION_RLE8).palette(PALETTE)
            .pixels(new byte[16]).build();

    IIOException exception = assertThrows(IIOException.class, () -> {
        setInput(mismatch);
        reader.read(0, null);
    });

    assertTrue(exception.getMessage().contains("Unsupported combination of bitCount/compression: 4/1"),
            "Unexpected message: " + exception.getMessage());
}

@Test
public void testRle4RequiresFourBit() {
    byte[] mismatch = new Bmp(4, 2, 8).compression(COMPRESSION_RLE4).palette(PALETTE)
            .pixels(new byte[16]).build();

    IIOException exception = assertThrows(IIOException.class, () -> {
        setInput(mismatch);
        reader.read(0, null);
    });

    assertTrue(exception.getMessage().contains("Unsupported combination of bitCount/compression: 8/2"),
            "Unexpected message: " + exception.getMessage());
}

