@Test
public void testRawImageType32BitWithAlphaMasksIsPacked() throws IOException {
    setInput(new Bmp(2, 2, 32).headerSize(V4_HEADER_SIZE)
            .masks(0x00FF0000, 0x0000FF00, 0x000000FF, 0xFF000000)
            .pixels(new byte[32]).build());

    ImageTypeSpecifier rawType = reader.getRawImageType(0);
    ColorModel colorModel = rawType.getColorModel();

    assertTrue(colorModel instanceof DirectColorModel, "Expected a DirectColorModel, was " + colorModel);
    DirectColorModel direct = (DirectColorModel) colorModel;
    assertEquals(0x00FF0000, direct.getRedMask());
    assertEquals(0x0000FF00, direct.getGreenMask());
    assertEquals(0x000000FF, direct.getBlueMask());
    assertEquals(0xFF000000, direct.getAlphaMask());
    assertEquals(4, rawType.getNumBands());
}

