        } catch (Throwable t) { System.out.println("3 colors req3 -> " + t); }

        // gradient with 256
        BufferedImage grad = new BufferedImage(64, 64, BufferedImage.TYPE_INT_RGB);
        for (int y = 0; y < 64; y++) for (int x = 0; x < 64; x++) grad.setRGB(x, y, (x * 4) << 16 | (y * 4) << 8 | ((x + y) * 2));
        for (int hints : new int[]{IndexImage.COLOR_SELECTION_FAST, IndexImage.COLOR_SELECTION_QUALITY, IndexImage.DITHER_DEFAULT}) {
            IndexColorModel icm = IndexImage.getIndexColorModel(grad, 256, hints);
            System.out.println("gradient 256 hints " + Integer.toHexString(hints) + " -> mapSize " + icm.getMapSize() + " bits " + icm.getPixelSize());
        }
        // diffusion vs none difference
        byte[] r = {0, (byte)255}, g = {0, (byte)255}, b = {0, (byte)255};
        IndexColorModel bw = new IndexColorModel(1, 2, r, g, b);
        BufferedImage g2 = new BufferedImage(32, 32, BufferedImage.TYPE_INT_RGB);
        for (int y = 0; y < 32; y++) for (int x = 0; x < 32; x++) { int v = x * 8; g2.setRGB(x, y, v << 16 | v << 8 | v); }
        BufferedImage none = IndexImage.getIndexedImage(g2, bw, null, IndexImage.DITHER_NONE);
        BufferedImage diff = IndexImage.getIndexedImage(g2, bw, null, IndexImage.DITHER_DIFFUSION);
        BufferedImage alt = IndexImage.getIndexedImage(g2, bw, null, IndexImage.DITHER_DIFFUSION_ALTSCANS);
        int dn = 0, da = 0;
        for (int y = 0; y < 32; y++) for (int x = 0; x < 32; x++) {
            if (none.getRGB(x,y) != diff.getRGB(x,y)) dn++;
            if (diff.getRGB(x,y) != alt.getRGB(x,y)) da++;
        }
        System.out.println("diff vs none differing pixels " + dn + ", alt vs diff " + da);
        // columns: none is vertical bands
        System.out.print("none row0: ");
        for (int x = 0; x < 32; x++) System.out.print(Integer.toHexString(none.getRGB(x,0)).charAt(2));
        System.out.println();
        System.out.print("diff row0: ");
        for (int x = 0; x < 32; x++) System.out.print(Integer.toHexString(diff.getRGB(x,0)).charAt(2));
        System.out.println();
        // source untouched
