package com.twelvemonkeys.image;

import java.awt.*;
import java.awt.image.*;
import java.util.*;

public class Exp5 {
    static BufferedImage stripes(int w,int h,int... colors) {
        BufferedImage bi = new BufferedImage(w,h,BufferedImage.TYPE_INT_RGB);
        for (int y=0;y<h;y++) for (int x=0;x<w;x++) bi.setRGB(x,y,colors[(x+y)%colors.length]);
        return bi;
    }
    public static void main(String[] a) throws Exception {
        int[] four = {0xFFFF0000, 0xFF00FF00, 0xFF0000FF, 0xFFFFFFFF};
        BufferedImage img = stripes(8,8,four);
        // 4 -> 2
        BufferedImage out = IndexImage.getIndexedImage(img, 2, IndexImage.DITHER_NONE);
        IndexColorModel icm = (IndexColorModel) out.getColorModel();
        System.out.println("4->2: type " + out.getType() + " mapSize " + icm.getMapSize());
        for (int i=0;i<icm.getMapSize();i++) System.out.printf("  %06x%n", icm.getRGB(i)&0xFFFFFF);
        Set<Integer> px = new LinkedHashSet<>();
        for (int y=0;y<8;y++) for (int x=0;x<8;x++) px.add(out.getRGB(x,y));
        for (int p : px) System.out.printf("  px %08x%n", p);
        // palette image overloads with plain RGB palette
        BufferedImage palRGB = stripes(3,1,0xFFFF0000,0xFF00FF00,0xFF0000FF);
        out = IndexImage.getIndexedImage(img, palRGB, IndexImage.DITHER_NONE);
        icm = (IndexColorModel) out.getColorModel();
        System.out.println("plain RGB palette 3-arg: type " + out.getType() + " mapSize " + icm.getMapSize() + " px0 " + Integer.toHexString(out.getRGB(0,0)) + " px1 "+Integer.toHexString(out.getRGB(1,0))+" px2 "+Integer.toHexString(out.getRGB(2,0))+" px3 "+Integer.toHexString(out.getRGB(3,0)));
        // 4-arg with plain RGB palette
        out = IndexImage.getIndexedImage(stripes(6,2,0xFFFF0000,0xFF00FF00,0xFF0000FF), palRGB, null, IndexImage.DITHER_NONE);
        icm = (IndexColorModel) out.getColorModel();
        System.out.println("plain RGB palette 4-arg: mapSize " + icm.getMapSize());
        for (int x=0;x<6;x++) System.out.printf("  %08x", out.getRGB(x,0));
        System.out.println();
        // transparent index sample
