package com.twelvemonkeys.image;

import java.awt.*;
import java.awt.image.*;
import java.util.*;

public class Exp7 {
    static final int RED = 0xFFFF0000, GREEN = 0xFF00FF00, BLUE = 0xFF0000FF, WHITE = 0xFFFFFFFF;
    static BufferedImage stripes(int w, int h, int... colors) {
        BufferedImage bi = new BufferedImage(w, h, BufferedImage.TYPE_INT_RGB);
        for (int y = 0; y < h; y++) for (int x = 0; x < w; x++) bi.setRGB(x, y, colors[(x + y) % colors.length]);
        return bi;
    }
    static void dump(String label, IndexColorModel icm) {
        System.out.print(label + " mapSize=" + icm.getMapSize() + " transp=" + icm.getTransparentPixel() + " :");
        Set<Integer> s = new TreeSet<>();
        for (int i = 0; i < icm.getMapSize(); i++) s.add(icm.getRGB(i));
        for (int v : s) System.out.printf(" %08x", v);
        System.out.println(" unique=" + s.size());
    }
    public static void main(String[] a) {
        BufferedImage four = stripes(16, 16, RED, GREEN, BLUE, WHITE);
        BufferedImage two = stripes(16, 16, 0xFF000000, WHITE);
        BufferedImage three = stripes(16, 16, RED, GREEN, BLUE);
        BufferedImage grad = new BufferedImage(64,64,BufferedImage.TYPE_INT_RGB);
        for (int y=0;y<64;y++) for (int x=0;x<64;x++) grad.setRGB(x,y,(x*4)<<16|(y*4)<<8|((x+y)*2));

        dump("four/16", IndexImage.getIndexColorModel(four, 16, IndexImage.DITHER_NONE));
        dump("four/4", IndexImage.getIndexColorModel(four, 4, IndexImage.DITHER_NONE));
        dump("four/3", IndexImage.getIndexColorModel(four, 3, IndexImage.DITHER_NONE));
        dump("four/2", IndexImage.getIndexColorModel(four, 2, IndexImage.DITHER_NONE));
        dump("four/16 transp", IndexImage.getIndexColorModel(four, 16, IndexImage.TRANSPARENCY_BITMASK));
        dump("two/16", IndexImage.getIndexColorModel(two, 16, IndexImage.DITHER_NONE));
        dump("three/16", IndexImage.getIndexColorModel(three, 16, IndexImage.DITHER_NONE));
        dump("grad/256 fast", IndexImage.getIndexColorModel(grad, 256, IndexImage.COLOR_SELECTION_FAST));
        dump("grad/256 quality", IndexImage.getIndexColorModel(grad, 256, IndexImage.COLOR_SELECTION_QUALITY));
        dump("grad/16 quality", IndexImage.getIndexColorModel(grad, 16, IndexImage.COLOR_SELECTION_QUALITY));
        dump("grad/16 fast", IndexImage.getIndexColorModel(grad, 16, IndexImage.COLOR_SELECTION_FAST));
        dump("palette3/256", IndexImage.getIndexColorModel(three, 256, IndexImage.DITHER_NONE));
        // indexed source
        IndexColorModel rgb3 = new IndexColorModel(8, 3, new byte[]{(byte)255,0,0}, new byte[]{0,(byte)255,0}, new byte[]{0,0,(byte)255});
        BufferedImage indexed3 = new BufferedImage(16,16,BufferedImage.TYPE_BYTE_INDEXED, rgb3);
        for (int y=0;y<16;y++) for (int x=0;x<16;x++) indexed3.getRaster().setSample(x,y,0,(x+y)%3);
        dump("indexed3/16", IndexImage.getIndexColorModel(indexed3, 16, IndexImage.DITHER_NONE));
        dump("indexed3/2", IndexImage.getIndexColorModel(indexed3, 2, IndexImage.DITHER_NONE));
        IndexColorModel rgb4 = new IndexColorModel(8, 4, new byte[]{(byte)255,0,0,(byte)255}, new byte[]{0,(byte)255,0,(byte)255}, new byte[]{0,0,(byte)255,(byte)255});
        BufferedImage indexed4 = new BufferedImage(16,16,BufferedImage.TYPE_BYTE_INDEXED, rgb4);
        for (int y=0;y<16;y++) for (int x=0;x<16;x++) indexed4.getRaster().setSample(x,y,0,(x+y)%4);
        dump("indexed4/2", IndexImage.getIndexColorModel(indexed4, 2, IndexImage.DITHER_NONE));
        dump("indexed4/16", IndexImage.getIndexColorModel(indexed4, 16, IndexImage.DITHER_NONE));
        // argb
        BufferedImage argb = new BufferedImage(8,8,BufferedImage.TYPE_INT_ARGB);
        for (int y=0;y<8;y++) for (int x=0;x<8;x++) argb.setRGB(x,y, x<4?0x00FF0000:0xFF00FF00);
        dump("argb/16 none", IndexImage.getIndexColorModel(argb, 16, IndexImage.DITHER_NONE));
        dump("argb/16 bitmask", IndexImage.getIndexColorModel(argb, 16, IndexImage.TRANSPARENCY_BITMASK));
        dump("argb/16 opaque", IndexImage.getIndexColorModel(argb, 16, IndexImage.TRANSPARENCY_OPAQUE));
        // deprecated
        dump("four/16 dep-fast", IndexImage.getIndexColorModel(four, 16, true));
        dump("four/16 dep-quality", IndexImage.getIndexColorModel(four, 16, false));
        // indexed image without dither through getIndexedImage variants
        BufferedImage out = IndexImage.getIndexedImage(four, 2, IndexImage.DITHER_NONE);
        System.out.println("four->2 type=" + out.getType() + " mapSize=" + ((IndexColorModel)out.getColorModel()).getMapSize());
        Set<Integer> px = new TreeSet<>();
        for (int y=0;y<16;y++) for (int x=0;x<16;x++) px.add(out.getRGB(x,y));
        System.out.print("  pixels:");
        for (int v: px) System.out.printf(" %08x", v);
        System.out.println();
        out = IndexImage.getIndexedImage(four, 4, IndexImage.DITHER_NONE);
        boolean exact = true;
        for (int y=0;y<16;y++) for (int x=0;x<16;x++) if (out.getRGB(x,y) != four.getRGB(x,y)) exact = false;
        System.out.println("four->4 exact=" + exact + " type=" + out.getType() + " mapSize=" + ((IndexColorModel)out.getColorModel()).getMapSize());
        out = IndexImage.getIndexedImage(four);
        exact = true;
        for (int y=0;y<16;y++) for (int x=0;x<16;x++) if (out.getRGB(x,y) != four.getRGB(x,y)) exact = false;
        System.out.println("four default exact=" + exact + " type=" + out.getType() + " mapSize=" + ((IndexColorModel)out.getColorModel()).getMapSize());
        out = IndexImage.getIndexedImage(two);
        exact = true;
        for (int y=0;y<16;y++) for (int x=0;x<16;x++) if (out.getRGB(x,y) != two.getRGB(x,y)) exact = false;
        System.out.println("two default exact=" + exact + " type=" + out.getType() + " mapSize=" + ((IndexColorModel)out.getColorModel()).getMapSize());
        // plain palette image overload
        out = IndexImage.getIndexedImage(three, three, IndexImage.DITHER_NONE);
        exact = true;
        for (int y=0;y<16;y++) for (int x=0;x<16;x++) if (out.getRGB(x,y) != three.getRGB(x,y)) exact = false;
        System.out.println("three/paletteImage exact=" + exact + " type=" + out.getType() + " mapSize=" + ((IndexColorModel)out.getColorModel()).getMapSize());
        out = IndexImage.getIndexedImage(three, indexed3, IndexImage.DITHER_NONE);
        exact = true;
        for (int y=0;y<16;y++) for (int x=0;x<16;x++) if (out.getRGB(x,y) != three.getRGB(x,y)) exact = false;
        System.out.println("three/indexedPalette exact=" + exact + " type=" + out.getType() + " mapSize=" + ((IndexColorModel)out.getColorModel()).getMapSize());
        // gradient default
        out = IndexImage.getIndexedImage(grad);
        System.out.println("grad default type=" + out.getType() + " mapSize=" + ((IndexColorModel)out.getColorModel()).getMapSize() + " size " + out.getWidth()+"x"+out.getHeight());
    }
}
