package com.twelvemonkeys.image;
import java.awt.*;
import java.awt.image.*;

public class Exp8 {
    static BufferedImage gradientImage(int width, int height) {
        BufferedImage image = new BufferedImage(width, height, BufferedImage.TYPE_INT_RGB);
        for (int y = 0; y < height; y++) for (int x = 0; x < width; x++) {
            int r = (x * 255) / (width - 1);
            int g = (y * 255) / (height - 1);
            int b = ((x + y) * 255) / (width + height - 2);
            image.setRGB(x, y, (r << 16) | (g << 8) | b);
        }
        return image;
    }
    public static void main(String[] a) {
        BufferedImage image = new BufferedImage(16, 16, BufferedImage.TYPE_INT_ARGB);
        for (int y = 0; y < 16; y++) for (int x = 0; x < 16; x++) {
            int c;
            if (x < 4) c = 0x00FF0000;
            else if (x < 8) c = 0x80FF0000;
            else if (x < 12) c = 0xFFFF0000;
            else c = 0xFF00FF00;
            image.setRGB(x, y, c);
        }
        BufferedImage withMatte = IndexImage.getIndexedImage(image, 256, Color.BLUE, IndexImage.DITHER_NONE | IndexImage.TRANSPARENCY_BITMASK);
        BufferedImage withoutMatte = IndexImage.getIndexedImage(image, 256, IndexImage.DITHER_NONE | IndexImage.TRANSPARENCY_BITMASK);
        IndexColorModel icm = (IndexColorModel) withMatte.getColorModel();
        System.out.println("with matte mapSize " + icm.getMapSize() + " transp " + icm.getTransparentPixel());
        for (int i=0;i<icm.getMapSize();i++) System.out.printf("  %08x%n", icm.getRGB(i));
        System.out.printf("px(0,0)=%08x px(5,0)=%08x px(10,0)=%08x px(15,0)=%08x%n", withMatte.getRGB(0,0), withMatte.getRGB(5,0), withMatte.getRGB(10,0), withMatte.getRGB(15,0));
        System.out.printf("no matte px(0,0)=%08x px(5,0)=%08x px(10,0)=%08x px(15,0)=%08x%n", withoutMatte.getRGB(0,0), withoutMatte.getRGB(5,0), withoutMatte.getRGB(10,0), withoutMatte.getRGB(15,0));

        // dither
        BufferedImage grad = gradientImage(32, 32);
        byte[] r = {0, (byte)255}, g = {0, (byte)255}, b = {0, (byte)255};
        IndexColorModel bw = new IndexColorModel(8, 2, r, g, b);
        BufferedImage none = IndexImage.getIndexedImage(grad, bw, null, IndexImage.DITHER_NONE);
        BufferedImage diff = IndexImage.getIndexedImage(grad, bw, null, IndexImage.DITHER_DIFFUSION);
        BufferedImage alt = IndexImage.getIndexedImage(grad, bw, null, IndexImage.DITHER_DIFFUSION_ALTSCANS);
        System.out.println("types " + none.getType() + "," + diff.getType() + "," + alt.getType() + " mapSizes " + ((IndexColorModel)none.getColorModel()).getMapSize()+","+((IndexColorModel)diff.getColorModel()).getMapSize());
        int dn=0, da=0;
        for (int y=0;y<32;y++) for (int x=0;x<32;x++) { if (none.getRGB(x,y)!=diff.getRGB(x,y)) dn++; if (alt.getRGB(x,y)!=diff.getRGB(x,y)) da++; }
        System.out.println("diff vs none differing " + dn + ", alt vs diff " + da + " of 1024");
        // opaque image bitmask palette size
        BufferedImage rgb = new BufferedImage(16,16,BufferedImage.TYPE_INT_RGB);
        for (int y=0;y<16;y++) for (int x=0;x<16;x++) rgb.setRGB(x,y,((x+y)%2==0)?0xFFFF0000:0xFF00FF00);
        BufferedImage o = IndexImage.getIndexedImage(rgb, 256, IndexImage.DITHER_NONE | IndexImage.TRANSPARENCY_BITMASK);
        System.out.println("opaque src + bitmask: mapSize " + ((IndexColorModel)o.getColorModel()).getMapSize() + " transparency " + o.getColorModel().getTransparency() + " px0 " + Integer.toHexString(o.getRGB(0,0)));
    }
}
