/**
 * Behavioural tests for the lossless JPEG scan decoder.
 *
 * <p>The synthetic JPEGs in this test class are deliberately tiny. Their entropy-coded data
 * contains only DC differences in categories 0 and 1, making every decoded sample and every
 * predictor result directly checkable from the JPEG lossless specification.</p>
 */
class JPEGLosslessDecoderTests {

    private static final int[] ONE_COMPONENT = {1};
    private static final int[] THREE_COMPONENTS = {1, 2, 3};
    private static final int[] FOUR_COMPONENTS = {1, 2, 3, 4};

    @Test
    void constructorRejectsNullSegments() {
