403	    private IndexColorModel getVGAPalette() throws IOException {
404	        if (!readPalette) {
405	            readHeader();
406	
407	            // Mark palette as read, to avoid further attempts
408	            readPalette = true;
409	
410	            if (header.getVersion() >= PCX.VERSION_3 || header.getVersion() == PCX.VERSION_2_8_PALETTE) {
411	                // We can't simply skip to an offset, as the RLE compression makes the file size unpredictable
412	                skipToEOF(imageInput);
413	
414	                int paletteSize = 256 * 3; // 256 * 3 for RGB
415	
416	                // Seek backwards from EOF
417	                long paletteStart = imageInput.getStreamPosition() - paletteSize - 1;
418	                if (paletteStart > imageInput.getFlushedPosition()) {
419	                    imageInput.seek(paletteStart);
420	
421	                    byte val = imageInput.readByte();
422	
423	                    if (val == PCX.VGA_PALETTE_MAGIC) {
424	                        byte[] palette = new byte[paletteSize];
425	                        imageInput.readFully(palette);
426	
427	                        vgaPalette = new IndexColorModel(8, 256, palette, 0, false);
428	                    }
429	                }
430	            }
431	        }
432	
433	        return vgaPalette;
434	    }
