437	    private static long skipToEOF(final ImageInputStream stream) throws IOException {
438	        long length = stream.length();
439	
440	        if (length > 0) {
441	            // Known length, skip there and we're done.
442	            stream.seek(length);
443	        }
444	        else {
445	            // Otherwise, seek to EOF the hard way.
446	            // First, store stream position...
447	            long pos = stream.getStreamPosition();
448	
449	            // ...skip 1k blocks until we're passed EOF...
450	            while (stream.skipBytes(1024L) > 0) {
451	                if (stream.read() == -1) {
452	                    break;
453	                }
454	
455	                pos = stream.getStreamPosition();
456	            }
457	
458	            // ...go back to last known pos...
459	            stream.seek(pos);
460	
461	            // ...finally seek until EOF one byte at a time. Done.
462	            while (stream.read() != -1) {
463	            }
464	        }
465	
466	        return stream.getStreamPosition();
467	    }
