        assertEquals(4, rawType.getNumBands());
        assertTrue(rawType.getColorModel().hasAlpha());

        List<ImageTypeSpecifier> imageTypes = toList(reader.getImageTypes(0));
        assertEquals(2, imageTypes.size());
        assertEquals(BufferedImage.TYPE_4BYTE_ABGR, imageTypes.get(0).getBufferedImageType());

