    @Test
    void readsRegionOfInterestMatchingTheFullImage() throws IOException {
        PSDImageReader reader = open(TEST_ORIGINAL);
        BufferedImage full = reader.read(0, null);

        ImageReadParam param = reader.getDefaultReadParam();
        param.setSourceRegion(new Rectangle(20, 30, 50, 40));
        BufferedImage region = reader.read(0, param);

        assertEquals(50, region.getWidth());
        assertEquals(40, region.getHeight());
        assertAll(
                () -> assertEquals(full.getRGB(20, 30), region.getRGB(0, 0)),
                () -> assertEquals(full.getRGB(69, 30), region.getRGB(49, 0)),
                () -> assertEquals(full.getRGB(20, 69), region.getRGB(0, 39)),
                () -> assertEquals(full.getRGB(69, 69), region.getRGB(49, 39))
        );
    }

    @Test
    void readsSubsampledImageMatchingTheFullImage() throws IOException {
        PSDImageReader reader = open(TEST_ORIGINAL);
        BufferedImage full = reader.read(0, null);

        ImageReadParam param = reader.getDefaultReadParam();
        param.setSourceSubsampling(3, 2, 0, 0);
        BufferedImage subsampled = reader.read(0, param);

        assertEquals(237, subsampled.getWidth());
        assertEquals(256, subsampled.getHeight());
        assertAll(
                () -> assertEquals(full.getRGB(0, 0), subsampled.getRGB(0, 0)),
                () -> assertEquals(full.getRGB(3, 2), subsampled.getRGB(1, 1)),
                () -> assertEquals(full.getRGB(708, 510), subsampled.getRGB(236, 255))
        );
    }

    @Test
    void readsGrayscaleCompositeAndAlphaLayer() throws IOException {
        PSDImageReader reader = open(TEST_GRAY);

        assertEquals(2, reader.getNumImages(true));
        assertEquals(710, reader.getWidth(0));
        assertEquals(512, reader.getHeight(0));
        assertEquals(710, reader.getWidth(1));
        assertEquals(512, reader.getHeight(1));

        ImageTypeSpecifier compositeType = reader.getRawImageType(0);
        assertEquals(1, compositeType.getNumBands());
        assertFalse(compositeType.getColorModel().hasAlpha());
        assertEquals(BufferedImage.TYPE_BYTE_GRAY, toList(reader.getImageTypes(0)).get(0).getBufferedImageType());

        ImageTypeSpecifier layerType = reader.getRawImageType(1);
        assertEquals(2, layerType.getNumBands());
        assertTrue(layerType.getColorModel().hasAlpha());

        BufferedImage layer = reader.read(1, null);
        assertEquals(710, layer.getWidth());
        assertEquals(512, layer.getHeight());
        assertEquals(2, layer.getRaster().getNumBands());
        assertTrue(layer.getColorModel().hasAlpha());
        assertEquals(255, layer.getRGB(355, 256) >>> 24);
    }

