package com.twelvemonkeys.imageio.plugins.webp.vp8;

import org.junit.jupiter.api.Test;

import java.lang.reflect.Field;

import static com.twelvemonkeys.imageio.plugins.webp.vp8.SubBlock.Plane.U;
import static com.twelvemonkeys.imageio.plugins.webp.vp8.SubBlock.Plane.V;
import static com.twelvemonkeys.imageio.plugins.webp.vp8.SubBlock.Plane.Y1;
import static org.junit.jupiter.api.Assertions.assertEquals;
import static org.junit.jupiter.api.Assertions.assertNotEquals;
import static org.junit.jupiter.api.Assertions.assertNotNull;
import static org.junit.jupiter.api.Assertions.assertTrue;

/**
 * Tests for {@link LoopFilter}. The filter is exercised through its package
 * level entry points, using real {@link MacroBlock}/{@link SubBlock} instances
 * so that the pixels actually written back by the filter can be inspected.
 * <p>
 * Pixel layout (see {@code getSegH}/{@code setSegH}): for an edge between a
 * "left" (p) and a "right" (q) sub block, rows of the sub block arrays are
 * interpreted as {@code P3, P2, P1, P0} (left sub block) and
 * {@code Q0, Q1, Q2, Q3} (right sub block).
 */
class LoopFilterTests {

    private static final int KEY_FRAME = 0;
    private static final int INTER_FRAME = 1;

    // --- entry point: loopFilterBlock dispatch ---------------------------------

    @Test
    void loopFilterBlockWithZeroFilterLevelLeavesEveryPixelUntouched() {
        MacroBlock cmb = macroBlock(100);
        MacroBlock lmb = macroBlock(120);
        MacroBlock tmb = macroBlock(120);
        cmb.setFilterLevel(0);

        int[][] cmbY = copy(cmb.getSubBlock(Y1, 0, 0).getDest());
        int[][] lmbY = copy(lmb.getSubBlock(Y1, 3, 0).getDest());

        LoopFilter.loopFilterBlock(cmb, lmb, tmb, KEY_FRAME, false, 0);
        LoopFilter.loopFilterBlock(cmb, lmb, tmb, KEY_FRAME, true, 0);

        assertPixelsUnchanged(cmb);
        assertPixelsUnchanged(lmb);
        assertPixelsUnchanged(tmb);
        assertPixelsUnchanged("luma untouched for level 0", cmbY, cmb.getSubBlock(Y1, 0, 0).getDest());
        assertPixelsUnchanged("neighbour untouched for level 0", lmbY, lmb.getSubBlock(Y1, 3, 0).getDest());
    }

    @Test
    void loopFilterBlockNormalModeFiltersLumaAndChroma() {
        MacroBlock cmb = macroBlock(100);
        MacroBlock lmb = macroBlock(120);
        cmb.setFilterLevel(40);

        LoopFilter.loopFilterBlock(cmb, lmb, null, KEY_FRAME, false, 0);

        assertTrue(edgeGap(cmb, lmb) < 20, "Normal mode must smooth the macro block edge");
        assertEquals(120, lmb.getSubBlock(U, 1, 0).getDest()[0][0], "Chroma edge must not be smoothed when neighbours are equal");
        assertFiltered(cmb, lmb, Y1);
        assertFiltered(cmb, lmb, U);
        assertFiltered(cmb, lmb, V);
        assertPixelsInRange(cmb);
        assertPixelsInRange(lmb);
    }

    @Test
    void loopFilterBlockSimpleModeOnlyTouchesLuma() {
        MacroBlock cmb = macroBlock(100);
        MacroBlock lmb = macroBlock(120);
        cmb.setFilterLevel(40);

        int[][] chromaOfNeighbour = copy(lmb.getSubBlock(U, 1, 0).getDest());

        LoopFilter.loopFilterBlock(cmb, lmb, null, KEY_FRAME, true, 0);

        assertTrue(edgeGap(cmb, lmb) < 20, "Simple mode must smooth the macro block edge");
        assertPixelsUnchanged("simple filter is luma only", chromaOfNeighbour, lmb.getSubBlock(U, 1, 0).getDest());
        assertPixelsUnchanged("simple filter is luma only", uniform(100), cmb.getSubBlock(U, 0, 0).getDest());
        assertPixelsUnchanged("simple filter is luma only", uniform(100), cmb.getSubBlock(V, 0, 0).getDest());
        assertPixelsInRange(cmb);
    }

    // --- luma (Y1) filtering ---------------------------------------------------

    @Test
    void yBlockPullEdgePixelsTowardsEachOther() {
        MacroBlock cmb = macroBlock(100);
        MacroBlock lmb = macroBlock(120);
        cmb.setFilterLevel(40);

        LoopFilter.loopFilterYBlock(cmb, lmb, null, 0, KEY_FRAME);

        for (int b = 0; b < 4; b++) {
            int[][] p = lmb.getSubBlock(Y1, 3, b).getDest();
            int[][] q = cmb.getSubBlock(Y1, 0, b).getDest();
            for (int a = 0; a < 4; a++) {
                assertTrue(p[3][a] < 120, "P0 must move towards the (brighter) Q pixels: " + p[3][a]);
                assertTrue(q[0][a] > 100, "Q0 must move towards the (darker) P pixels: " + q[0][a]);
                assertTrue(Math.abs(p[3][a] - q[0][a]) < 20, "Edge difference must shrink");
                // P1 and Q1 are adjusted as well by the 7 tap filter
                assertNotEquals(120, p[2][a], "P1 must be adjusted");
                assertNotEquals(100, q[1][a], "Q1 must be adjusted");
            }
        }
        assertPixelsInRange(cmb);
        assertPixelsInRange(lmb);
    }

    @Test
    void yBlockFilteringIsLocalToTheMacroBlockEdge() {
        MacroBlock cmb = macroBlock(100);
        MacroBlock lmb = macroBlock(120);
        cmb.setFilterLevel(40);

        LoopFilter.loopFilterYBlock(cmb, lmb, null, 0, KEY_FRAME);

        for (int b = 0; b < 4; b++) {
            // Sub blocks that are not adjacent to the filtered edge must be left alone
            assertPixelsUnchanged("2nd sub block column is far from the edge", uniform(100),
                    cmb.getSubBlock(Y1, 2, b).getDest());
            assertPixelsUnchanged("3rd sub block column is far from the edge", uniform(100),
                    cmb.getSubBlock(Y1, 3, b).getDest());
            assertPixelsUnchanged("left neighbour, far sub block is read only", uniform(120),
                    lmb.getSubBlock(Y1, 0, b).getDest());
        }
    }

    @Test
    void yBlockFilteringDoesNotTouchChromaOrY2() {
        MacroBlock cmb = macroBlock(100);
        MacroBlock lmb = macroBlock(120);
        cmb.setFilterLevel(40);

        cmb.getY2SubBlock().setDest(uniform(77));
        lmb.getY2SubBlock().setDest(uniform(177));

        LoopFilter.loopFilterYBlock(cmb, lmb, null, 0, KEY_FRAME);

        assertPixelsUnchanged("Y2 is not part of the loop filter", uniform(77), cmb.getY2SubBlock().getDest());
        assertPixelsUnchanged("Y2 is not part of the loop filter", uniform(177), lmb.getY2SubBlock().getDest());
        assertPixelsUnchanged("chroma untouched by luma filter", uniform(100), cmb.getSubBlock(U, 0, 0).getDest());
        assertPixelsUnchanged("chroma untouched by luma filter", uniform(120), lmb.getSubBlock(V, 1, 1).getDest());
    }

    @Test
    void yBlockDoesNothingWhenEdgeDifferenceExceedsTheEdgeLimit() {
        // Huge step (200 vs 20): the threshold check must disable filtering
        MacroBlock cmb = macroBlock(20);
        MacroBlock lmb = macroBlock(200);
        cmb.setFilterLevel(40);

        LoopFilter.loopFilterYBlock(cmb, lmb, null, 0, KEY_FRAME);

        for (int b = 0; b < 4; b++) {
            assertPixelsUnchanged("strong edge must not be blurred", uniform(20),
                    cmb.getSubBlock(Y1, 0, b).getDest());
            assertPixelsUnchanged("strong edge must not be blurred", uniform(200),
                    lmb.getSubBlock(Y1, 3, b).getDest());
        }
    }

    @Test
    void yBlockSharpnessLimitsInteriorDifferenceTolerance() {
        // p3 == p2 == p1 = 130, p0 = 100, q0..q3 = 100: an interior difference of 30
        MacroBlock cmbSoft = macroBlock(100);
        MacroBlock lmbSoft = macroBlock(100);
        setRows(lmbSoft.getSubBlock(Y1, 3, 0), 130, 130, 130, 100);
        cmbSoft.setFilterLevel(40);
        LoopFilter.loopFilterYBlock(cmbSoft, lmbSoft, null, 0, KEY_FRAME);
        assertNotEquals(100, lmbSoft.getSubBlock(Y1, 3, 0).getDest()[3][0],
                "Sharpness 0 tolerates the interior difference of 30, filter must run");

        MacroBlock cmbSharp = macroBlock(100);
        MacroBlock lmbSharp = macroBlock(100);
        setRows(lmbSharp.getSubBlock(Y1, 3, 0), 130, 130, 130, 100);
        cmbSharp.setFilterLevel(40);
        LoopFilter.loopFilterYBlock(cmbSharp, lmbSharp, null, 7, KEY_FRAME);
        assertPixelsUnchanged("Sharpness 7 must disable filtering for this interior difference",
                uniform(100), cmbSharp.getSubBlock(Y1, 0, 0).getDest());
        assertPixelsUnchanged("Sharpness 7 must disable filtering for this interior difference",
                rows(130, 130, 130, 100), lmbSharp.getSubBlock(Y1, 3, 0).getDest());
    }

    @Test
    void yBlockHighEdgeVarianceUsesOuterTapsOnly() {
        // p1 - p0 = 14 > hev threshold (2 for key frames with level >= 40)
        MacroBlock cmbHev = macroBlock(100);
        MacroBlock lmbHev = macroBlock(100);
        setRows(lmbHev.getSubBlock(Y1, 3, 0), 114, 114, 114, 100);
        cmbHev.setFilterLevel(40);
        LoopFilter.loopFilterYBlock(cmbHev, lmbHev, null, 0, KEY_FRAME);

        int[][] pHev = lmbHev.getSubBlock(Y1, 3, 0).getDest();
        int[][] qHev = cmbHev.getSubBlock(Y1, 0, 0).getDest();
        assertEquals(114, pHev[1][0], "High edge variance: P2 must stay untouched");
        assertEquals(100, qHev[2][0], "High edge variance: Q2 must stay untouched");
        assertNotEquals(100, pHev[3][0], "The pixels adjacent to the edge are always adjusted");

        // No high edge variance, but a clear step: the full 7 tap filter runs
        MacroBlock cmbWide = macroBlock(100);
        MacroBlock lmbWide = macroBlock(120);
        cmbWide.setFilterLevel(40);
        LoopFilter.loopFilterYBlock(cmbWide, lmbWide, null, 0, KEY_FRAME);

        int[][] pWide = lmbWide.getSubBlock(Y1, 3, 0).getDest();
        int[][] qWide = cmbWide.getSubBlock(Y1, 0, 0).getDest();
        assertNotEquals(120, pWide[1][0], "Low edge variance: P2 is adjusted by the wide filter");
        assertNotEquals(100, qWide[2][0], "Low edge variance: Q2 is adjusted by the wide filter");
    }

    @Test
    void yBlockFiltersInternalSubBlockEdgesWithoutNeighbours() {
        MacroBlock cmb = macroBlock(100);
        // First sub block column darker than the rest: an internal (sub block) edge at column 0|1
        for (int b = 0; b < 4; b++) {
            cmb.getSubBlock(Y1, 0, b).setDest(uniform(120));
        }
        cmb.setFilterLevel(40);

        LoopFilter.loopFilterYBlock(cmb, null, null, 0, KEY_FRAME);

        for (int b = 0; b < 4; b++) {
            int[][] p = cmb.getSubBlock(Y1, 0, b).getDest();
            int[][] q = cmb.getSubBlock(Y1, 1, b).getDest();
            assertTrue(p[3][0] < 120, "Internal edge must be filtered from the left side: " + p[3][0]);
            assertTrue(q[0][0] > 100, "Internal edge must be filtered from the right side: " + q[0][0]);
            assertPixelsUnchanged("sub block column 2 is untouched", uniform(100),
                    cmb.getSubBlock(Y1, 2, b).getDest());
        }
    }

    @Test
    void yBlockSkipsInternalEdgesWhenSkipInnerLoopFilterIsSet() throws Exception {
        MacroBlock cmb = macroBlock(100);
        for (int b = 0; b < 4; b++) {
            cmb.getSubBlock(Y1, 0, b).setDest(uniform(120));
        }
        cmb.setFilterLevel(40);
        setSkipInnerLoopFilter(cmb, true);

        LoopFilter.loopFilterYBlock(cmb, null, null, 0, KEY_FRAME);

        for (int b = 0; b < 4; b++) {
            assertPixelsUnchanged("skip_inner_lf disables the internal edge filter", uniform(120),
                    cmb.getSubBlock(Y1, 0, b).getDest());
            assertPixelsUnchanged("skip_inner_lf disables the internal edge filter", uniform(100),
                    cmb.getSubBlock(Y1, 1, b).getDest());
        }
    }

    // --- chroma (U/V) filtering -----------------------------------------------

    @Test
    void uvBlockFilterBothChromaPlanesAtTheLeftEdge() {
        MacroBlock cmb = macroBlock(100);
        MacroBlock lmb = macroBlock(120);
        cmb.setFilterLevel(40);

        LoopFilter.loopFilterUVBlock(cmb, lmb, null, 0, KEY_FRAME);

        assertFiltered(cmb, lmb, U);
        assertFiltered(cmb, lmb, V);
        assertPixelsUnchanged("luma untouched by chroma filter", uniform(100), cmb.getSubBlock(Y1, 0, 0).getDest());
        assertPixelsUnchanged("luma untouched by chroma filter", uniform(120), lmb.getSubBlock(Y1, 3, 0).getDest());
        assertPixelsInRange(cmb);
        assertPixelsInRange(lmb);
    }

    @Test
    void uvBlockDoesNothingWhenFilterLevelIsZero() {
        MacroBlock cmb = macroBlock(100);
        MacroBlock lmb = macroBlock(120);
        cmb.setFilterLevel(0);

        LoopFilter.loopFilterUVBlock(cmb, lmb, null, 0, KEY_FRAME);

        assertPixelsUnchanged("filter level 0 disables chroma filtering", uniform(100), cmb.getSubBlock(U, 0, 0).getDest());
        assertPixelsUnchanged("filter level 0 disables chroma filtering", uniform(120), lmb.getSubBlock(U, 1, 0).getDest());
        assertPixelsUnchanged("filter level 0 disables chroma filtering", uniform(120), lmb.getSubBlock(V, 1, 1).getDest());
    }

    @Test
    void uvBlockDoesNothingForStrongEdges() {
        MacroBlock cmb = macroBlock(20);
        MacroBlock lmb = macroBlock(220);
        cmb.setFilterLevel(40);

        LoopFilter.loopFilterUVBlock(cmb, lmb, null, 0, KEY_FRAME);

        assertPixelsUnchanged("strong chroma edge must not be blurred", uniform(20), cmb.getSubBlock(U, 0, 0).getDest());
        assertPixelsUnchanged("strong chroma edge must not be blurred", uniform(220), lmb.getSubBlock(V, 1, 0).getDest());
    }

    @Test
    void uvBlockFilterInternalEdgesWithoutNeighbours() {
        MacroBlock cmb = macroBlock(100);
        for (int i = 0; i < 2; i++) {
            cmb.getSubBlock(U, 0, i).setDest(uniform(120));
            cmb.getSubBlock(V, 0, i).setDest(uniform(120));
        }
        cmb.setFilterLevel(40);

        LoopFilter.loopFilterUVBlock(cmb, null, null, 0, INTER_FRAME);

        assertFiltered(cmb, cmb, U);
        assertFiltered(cmb, cmb, V);
        assertPixelsInRange(cmb);
    }

    // --- simple filter ---------------------------------------------------------

    @Test
    void simpleBlockSmoothsLumaEdgeOnly() {
        MacroBlock cmb = macroBlock(100);
        MacroBlock lmb = macroBlock(120);
        cmb.setFilterLevel(40);

        LoopFilter.loopFilterSimpleBlock(cmb, lmb, null, 0);

        assertFiltered(cmb, lmb, Y1);
        assertTrue(edgeGap(cmb, lmb) < 20, "Simple filter must reduce the edge difference");
        assertPixelsUnchanged("simple filter ignores chroma", uniform(100), cmb.getSubBlock(U, 0, 0).getDest());
        assertPixelsUnchanged("simple filter ignores chroma", uniform(120), lmb.getSubBlock(V, 1, 0).getDest());
    }

    @Test
    void simpleBlockDoesNothingWhenFilterLevelIsZero() {
        MacroBlock cmb = macroBlock(100);
        MacroBlock lmb = macroBlock(120);
        cmb.setFilterLevel(0);

        LoopFilter.loopFilterSimpleBlock(cmb, lmb, null, 0);

        assertPixelsUnchanged("filter level 0 disables filtering", uniform(100), cmb.getSubBlock(Y1, 0, 0).getDest());
        assertPixelsUnchanged("filter level 0 disables filtering", uniform(120), lmb.getSubBlock(Y1, 3, 0).getDest());
    }

    @Test
    void simpleBlockDoesNothingForStrongEdges() {
        MacroBlock cmb = macroBlock(20);
        MacroBlock lmb = macroBlock(220);
        cmb.setFilterLevel(40);

        LoopFilter.loopFilterSimpleBlock(cmb, lmb, null, 0);

        assertPixelsUnchanged("strong edge must not be blurred", uniform(20), cmb.getSubBlock(Y1, 0, 0).getDest());
        assertPixelsUnchanged("strong edge must not be blurred", uniform(220), lmb.getSubBlock(Y1, 3, 0).getDest());
    }

    // --- robustness ------------------------------------------------------------

    @Test
    void filteringClampedExtremePixelValues() {
        MacroBlock cmb = macroBlock(0);
        MacroBlock lmb = macroBlock(255);
        MacroBlock tmb = macroBlock(255);
        cmb.setFilterLevel(63);

        LoopFilter.loopFilterBlock(cmb, lmb, tmb, KEY_FRAME, false, 0);
        LoopFilter.loopFilterBlock(cmb, lmb, tmb, KEY_FRAME, true, 0);

        assertPixelsInRange(cmb);
        assertPixelsInRange(lmb);
        assertPixelsInRange(tmb);
    }

    @Test
    void filteringWithoutNeighboursDoesNotFail() {
        MacroBlock cmb = macroBlock(100);
        cmb.setFilterLevel(20);

        LoopFilter.loopFilterBlock(cmb, null, null, INTER_FRAME, false, 0);
        LoopFilter.loopFilterBlock(cmb, null, null, INTER_FRAME, true, 0);

        assertNotNull(cmb.getSubBlock(Y1, 0, 0).getDest());
        assertPixelsInRange(cmb);
    }

    @Test
    void frameTypeAndSharpnessVariantsKeepPixelsInRange() {
        for (int frameType : new int[] {KEY_FRAME, INTER_FRAME}) {
            for (int sharpness = 0; sharpness <= 7; sharpness++) {
                for (int level : new int[] {1, 14, 15, 19, 20, 39, 40, 63}) {
                    MacroBlock cmb = macroBlock(100);
                    MacroBlock lmb = macroBlock(115);
                    MacroBlock tmb = macroBlock(85);
                    cmb.setFilterLevel(level);

                    LoopFilter.loopFilterYBlock(cmb, lmb, tmb, sharpness, frameType);
                    LoopFilter.loopFilterUVBlock(cmb, lmb, tmb, sharpness, frameType);
                    LoopFilter.loopFilterSimpleBlock(cmb, lmb, tmb, sharpness);

                    assertPixelsInRange(cmb);
                    assertPixelsInRange(lmb);
                    assertPixelsInRange(tmb);
                }
            }
        }
    }

    // --- helpers ---------------------------------------------------------------

    private static MacroBlock macroBlock(int value) {
        MacroBlock mb = new MacroBlock(0, 0, true);
        for (int x = 0; x < 4; x++) {
            for (int y = 0; y < 4; y++) {
                mb.getSubBlock(Y1, x, y).setDest(uniform(value));
            }
        }
        for (int x = 0; x < 2; x++) {
            for (int y = 0; y < 2; y++) {
                mb.getSubBlock(U, x, y).setDest(uniform(value));
                mb.getSubBlock(V, x, y).setDest(uniform(value));
            }
        }
        mb.getY2SubBlock().setDest(uniform(value));
        return mb;
    }

    private static int[][] uniform(int value) {
        return rows(value, value, value, value);
    }

    private static int[][] rows(int r0, int r1, int r2, int r3) {
        return new int[][] {
                {r0, r0, r0, r0},
                {r1, r1, r1, r1},
                {r2, r2, r2, r2},
                {r3, r3, r3, r3}
        };
    }

    private static void setRows(SubBlock sb, int r0, int r1, int r2, int r3) {
        sb.setDest(rows(r0, r1, r2, r3));
    }

    private static int[][] copy(int[][] source) {
        int[][] result = new int[source.length][];
        for (int i = 0; i < source.length; i++) {
            result[i] = source[i].clone();
        }
        return result;
    }

    private static void setSkipInnerLoopFilter(MacroBlock mb, boolean value) throws Exception {
        Field field = MacroBlock.class.getDeclaredField("skipInnerLoopFilter");
        field.setAccessible(true);
        field.setBoolean(mb, value);
    }

    /** Largest edge gap (|P0 - Q0|) over the left edge of the luma plane. */
    private static int edgeGap(MacroBlock cmb, MacroBlock lmb) {
        int gap = 0;
        for (int b = 0; b < 4; b++) {
            int p0 = lmb.getSubBlock(Y1, 3, b).getDest()[3][0];
            int q0 = cmb.getSubBlock(Y1, 0, b).getDest()[0][0];
            gap = Math.max(gap, Math.abs(p0 - q0));
        }
        return gap;
    }

    private static void assertFiltered(MacroBlock cmb, MacroBlock lmb, SubBlock.Plane plane) {
        int columns = plane == Y1 ? 4 : 2;
        boolean filtered = false;
        for (int b = 0; b < columns && !filtered; b++) {
            int[][] q = cmb.getSubBlock(plane, 0, b).getDest();
            for (int r = 0; r < 4; r++) {
                for (int c = 0; c < 4; c++) {
                    if (q[r][c] != 100) {
                        filtered = true;
                    }
                }
            }
        }
        assertTrue(filtered, plane + " plane was expected to be filtered (P/Q values of 100 expected)");
    }

    private static void assertPixelsInRange(MacroBlock mb) {
        for (int x = 0; x < 4; x++) {
            for (int y = 0; y < 4; y++) {
                assertInRange(mb.getSubBlock(Y1, x, y).getDest(), "Y1[" + x + "," + y + "]");
            }
        }
        for (int x = 0; x < 2; x++) {
            for (int y = 0; y < 2; y++) {
                assertInRange(mb.getSubBlock(U, x, y).getDest(), "U[" + x + "," + y + "]");
                assertInRange(mb.getSubBlock(V, x, y).getDest(), "V[" + x + "," + y + "]");
            }
        }
        assertInRange(mb.getY2SubBlock().getDest(), "Y2");
    }

    private static void assertInRange(int[][] dest, String label) {
        for (int[] row : dest) {
            for (int value : row) {
                assertTrue(value >= 0 && value <= 255, label + " out of range: " + value);
            }
        }
    }

    private static void assertPixelsUnchanged(MacroBlock mb) {
        int[][] reference = mb.getSubBlock(Y1, 0, 0).getDest();
        int value = reference[0][0];
        for (int x = 0; x < 4; x++) {
            for (int y = 0; y < 4; y++) {
                assertPixelsUnchanged("Y1[" + x + "," + y + "]", uniform(value), mb.getSubBlock(Y1, x, y).getDest());
            }
        }
    }

    private static void assertPixelsUnchanged(String message, int[][] expected, int[][] actual) {
        for (int r = 0; r < expected.length; r++) {
            for (int c = 0; c < expected[r].length; c++) {
                assertEquals(expected[r][c], actual[r][c], message + " at [" + r + "][" + c + "]");
            }
        }
    }
}
