package com.twelvemonkeys.imageio.plugins.webp.vp8;

import org.junit.jupiter.api.Test;

import java.lang.reflect.Field;

import static com.twelvemonkeys.imageio.plugins.webp.vp8.SubBlock.Plane.U;
import static com.twelvemonkeys.imageio.plugins.webp.vp8.SubBlock.Plane.V;
import static com.twelvemonkeys.imageio.plugins.webp.vp8.SubBlock.Plane.Y1;
import static com.twelvemonkeys.imageio.plugins.webp.vp8.SubBlock.Plane.Y2;
import static org.junit.jupiter.api.Assertions.assertEquals;
import static org.junit.jupiter.api.Assertions.assertNotEquals;
import static org.junit.jupiter.api.Assertions.assertTrue;

/**
 * Tests for {@link LoopFilter}, exercised through its package level entry
 * points using real {@link MacroBlock}/{@link SubBlock} instances, so that the
 * pixels the filter writes back can be inspected.
 * <p>
 * Horizontal edge layout (see {@code getSegH}/{@code setSegH}): for an edge
 * between a "left" ({@code p}, last sub block column of the left macro block)
 * and a "right" ({@code q}, first sub block column of the current macro block)
 * sub block, the <em>rows</em> of the sub block sample arrays are interpreted
 * as {@code P3, P2, P1, P0} (left) and {@code Q0, Q1, Q2, Q3} (right).
 */
class LoopFilterTests {

    private static final int KEY_FRAME = 0;
    private static final int INTER_FRAME = 1;

    // --- loopFilterBlock: dispatching -----------------------------------------

    @Test
    void noFilteringAtAllWhenFilterLevelIsZero() {
        MacroBlock cmb = macroBlock(100);
        MacroBlock lmb = macroBlock(120);
        MacroBlock tmb = macroBlock(120);
        cmb.setFilterLevel(0);

        Snap cmbSnap = new Snap(cmb);
        Snap lmbSnap = new Snap(lmb);
        Snap tmbSnap = new Snap(tmb);

        LoopFilter.loopFilterBlock(cmb, lmb, tmb, KEY_FRAME, false, 0);
        LoopFilter.loopFilterBlock(cmb, lmb, tmb, KEY_FRAME, true, 0);
        LoopFilter.loopFilterBlock(cmb, lmb, tmb, INTER_FRAME, false, 3);

        cmbSnap.assertUnchanged(cmb, "current macro block");
        lmbSnap.assertUnchanged(lmb, "left macro block");
        tmbSnap.assertUnchanged(tmb, "top macro block");
    }

    @Test
    void normalModeFiltersLumaAndChroma() {
        MacroBlock cmb = macroBlock(100);
        MacroBlock lmb = macroBlock(120);
        cmb.setFilterLevel(40);

        Snap cmbSnap = new Snap(cmb);
        Snap lmbSnap = new Snap(lmb);

        LoopFilter.loopFilterBlock(cmb, lmb, null, KEY_FRAME, false, 0);

        cmbSnap.assertPlaneChanged(cmb, Y1, "luma");
        cmbSnap.assertPlaneChanged(cmb, U, "chroma U");
        cmbSnap.assertPlaneChanged(cmb, V, "chroma V");
        cmbSnap.assertPlaneUnchanged(cmb, Y2, "Y2");
        lmbSnap.assertPlaneChanged(lmb, Y1, "neighbour luma");

        assertTrue(edgeGap(cmb, lmb, Y1) < 20, "The macro block edge must be smoothed");
    }

    @Test
    void simpleModeFiltersLumaOnly() {
        MacroBlock cmb = macroBlock(100);
        MacroBlock lmb = macroBlock(120);
        cmb.setFilterLevel(40);

        Snap cmbSnap = new Snap(cmb);
        Snap lmbSnap = new Snap(lmb);

        LoopFilter.loopFilterBlock(cmb, lmb, null, KEY_FRAME, true, 0);

        cmbSnap.assertPlaneChanged(cmb, Y1, "luma");
        cmbSnap.assertPlaneUnchanged(cmb, U, "chroma U");
        cmbSnap.assertPlaneUnchanged(cmb, V, "chroma V");
        lmbSnap.assertPlaneUnchanged(lmb, U, "chroma U of the neighbour");
        assertTrue(edgeGap(cmb, lmb, Y1) < 20, "The macro block edge must be smoothed");
    }

    // --- luma (Y1) filtering ---------------------------------------------------

    @Test
    void yBlockPullsEdgePixelsTowardsEachOther() {
        MacroBlock cmb = macroBlock(100);
        MacroBlock lmb = macroBlock(120);
        cmb.setFilterLevel(40);

        LoopFilter.loopFilterYBlock(cmb, lmb, null, 0, KEY_FRAME);

        for (int b = 0; b < 4; b++) {
            int[][] p = lmb.getSubBlock(Y1, 3, b).getDest();
            int[][] q = cmb.getSubBlock(Y1, 0, b).getDest();
            for (int a = 0; a < 4; a++) {
                assertTrue(p[3][a] < 120, "P0 must move towards the dark side: " + p[3][a]);
                assertTrue(q[0][a] > 100, "Q0 must move towards the bright side: " + q[0][a]);
                assertTrue(Math.abs(p[3][a] - q[0][a]) < 20, "Edge difference must shrink");
                assertNotEquals(120, p[2][a], "P1 must be adjusted");
                assertNotEquals(100, q[1][a], "Q1 must be adjusted");
            }
            assertPlaneInRange(cmb);
        }
    }

    @Test
    void yBlockFilteringIsLocalToTheFilteredEdge() {
        MacroBlock cmb = macroBlock(100);
        MacroBlock lmb = macroBlock(120);
        cmb.setFilterLevel(40);

        LoopFilter.loopFilterYBlock(cmb, lmb, null, 0, KEY_FRAME);

        for (int b = 0; b < 4; b++) {
            assertPixels("sub block column 2 is far from the edge", uniform(100), cmb.getSubBlock(Y1, 2, b).getDest());
            assertPixels("sub block column 3 is far from the edge", uniform(100), cmb.getSubBlock(Y1, 3, b).getDest());
            assertPixels("neighbour sub block column 0 is not written", uniform(120), lmb.getSubBlock(Y1, 0, b).getDest());
        }
    }

    @Test
    void yBlockFilteringDoesNotTouchChromaOrY2() {
        MacroBlock cmb = macroBlock(100);
        MacroBlock lmb = macroBlock(120);
        cmb.setFilterLevel(40);
        cmb.getY2SubBlock().setDest(uniform(77));
        lmb.getY2SubBlock().setDest(uniform(177));

        Snap cmbSnap = new Snap(cmb);
        Snap lmbSnap = new Snap(lmb);

        LoopFilter.loopFilterYBlock(cmb, lmb, null, 0, KEY_FRAME);

        cmbSnap.assertPlaneUnchanged(cmb, U, "chroma U");
        cmbSnap.assertPlaneUnchanged(cmb, V, "chroma V");
        cmbSnap.assertPlaneUnchanged(cmb, Y2, "Y2");
        lmbSnap.assertPlaneUnchanged(lmb, U, "chroma U of the neighbour");
        lmbSnap.assertPlaneUnchanged(lmb, V, "chroma V of the neighbour");
        lmbSnap.assertPlaneUnchanged(lmb, Y2, "Y2 of the neighbour");
    }

    @Test
    void yBlockDoesNothingWhenEdgeDifferenceExceedsTheEdgeLimit() {
        // Strong edge (20 vs 200): the threshold check must disable filtering
        MacroBlock cmb = macroBlock(20);
        MacroBlock lmb = macroBlock(200);
        cmb.setFilterLevel(40);

        Snap cmbSnap = new Snap(cmb);
        Snap lmbSnap = new Snap(lmb);

        LoopFilter.loopFilterYBlock(cmb, lmb, null, 0, KEY_FRAME);

        cmbSnap.assertUnchanged(cmb, "current macro block");
        lmbSnap.assertUnchanged(lmb, "left macro block");
    }

    @Test
    void sharpnessLevelLimitsInteriorDifferenceTolerance() {
        // P3 == P2 == P1 == 130, P0 == Q0..Q3 == 100: interior difference of 30
        MacroBlock cmbSoft = macroBlock(100);
        MacroBlock lmbSoft = macroBlock(100);
        setRows(lmbSoft.getSubBlock(Y1, 3, 0), 130, 130, 130, 100);
        cmbSoft.setFilterLevel(40);

        LoopFilter.loopFilterYBlock(cmbSoft, lmbSoft, null, 0, KEY_FRAME);

        assertNotEquals(100, lmbSoft.getSubBlock(Y1, 3, 0).getDest()[3][0],
                "With sharpness 0 the interior difference of 30 is tolerated, filtering must happen");

        MacroBlock cmbSharp = macroBlock(100);
        MacroBlock lmbSharp = macroBlock(100);
        setRows(lmbSharp.getSubBlock(Y1, 3, 0), 130, 130, 130, 100);
        cmbSharp.setFilterLevel(40);
        Snap cmbSharpSnap = new Snap(cmbSharp);
        Snap lmbSharpSnap = new Snap(lmbSharp);

        LoopFilter.loopFilterYBlock(cmbSharp, lmbSharp, null, 7, KEY_FRAME);

        cmbSharpSnap.assertUnchanged(cmbSharp, "current macro block (sharpness 7)");
        lmbSharpSnap.assertUnchanged(lmbSharp, "left macro block (sharpness 7)");
    }

    @Test
    void yBlockHighEdgeVarianceUsesOuterTapsOnly() {
        // |P1 - P0| == 14 exceeds the key frame HEV threshold of 2, but stays
        // within the interior limit of 40.
        MacroBlock cmbHev = macroBlock(100);
        MacroBlock lmbHev = macroBlock(100);
        setRows(lmbHev.getSubBlock(Y1, 3, 0), 114, 114, 114, 100);
        cmbHev.setFilterLevel(40);

        LoopFilter.loopFilterYBlock(cmbHev, lmbHev, null, 0, KEY_FRAME);

        int[][] pHev = lmbHev.getSubBlock(Y1, 3, 0).getDest();
        int[][] qHev = cmbHev.getSubBlock(Y1, 0, 0).getDest();
        assertEquals(114, pHev[1][0], "High edge variance: P2 must stay untouched");
        assertEquals(100, qHev[2][0], "High edge variance: Q2 must stay untouched");
        assertNotEquals(100, pHev[3][0], "Pixels adjacent to the edge are always adjusted");

        // No high edge variance, but a clear step: the wide 7 tap filter runs
        MacroBlock cmbWide = macroBlock(100);
        MacroBlock lmbWide = macroBlock(120);
        cmbWide.setFilterLevel(40);

        LoopFilter.loopFilterYBlock(cmbWide, lmbWide, null, 0, KEY_FRAME);

        int[][] pWide = lmbWide.getSubBlock(Y1, 3, 0).getDest();
        int[][] qWide = cmbWide.getSubBlock(Y1, 0, 0).getDest();
        assertNotEquals(120, pWide[1][0], "Low edge variance: P2 is adjusted by the wide filter");
        assertNotEquals(100, qWide[2][0], "Low edge variance: Q2 is adjusted by the wide filter");
    }

    @Test
    void yBlockFiltersInternalSubBlockEdgesWithoutNeighbours() {
        MacroBlock cmb = macroBlock(100);
        for (int b = 0; b < 4; b++) {
            cmb.getSubBlock(Y1, 0, b).setDest(uniform(120));
        }
        cmb.setFilterLevel(40);

        LoopFilter.loopFilterYBlock(cmb, null, null, 0, KEY_FRAME);

        for (int b = 0; b < 4; b++) {
            int[][] p = cmb.getSubBlock(Y1, 0, b).getDest();
            int[][] q = cmb.getSubBlock(Y1, 1, b).getDest();
            assertTrue(p[3][0] < 120, "Internal edge must be filtered from the left: " + p[3][0]);
            assertTrue(q[0][0] > 100, "Internal edge must be filtered from the right: " + q[0][0]);
            assertPixels("sub block column 2 is untouched", uniform(100), cmb.getSubBlock(Y1, 2, b).getDest());
        }
    }

    @Test
    void yBlockSkipsInternalEdgesWhenSkipInnerLoopFilterIsSet() throws Exception {
        MacroBlock cmb = macroBlock(100);
        for (int b = 0; b < 4; b++) {
            cmb.getSubBlock(Y1, 0, b).setDest(uniform(120));
        }
        cmb.setFilterLevel(40);
        setSkipInnerLoopFilter(cmb, true);
        assertTrue(cmb.isSkip_inner_lf(), "Precondition: inner loop filter is skipped");

        Snap snap = new Snap(cmb);
        LoopFilter.loopFilterYBlock(cmb, null, null, 0, KEY_FRAME);

        snap.assertUnchanged(cmb, "macro block with skip_inner_lf set");
    }

    // --- chroma (U/V) filtering -----------------------------------------------

    @Test
    void uvBlockFiltersBothChromaPlanes() {
        MacroBlock cmb = macroBlock(100);
        MacroBlock lmb = macroBlock(120);
        cmb.setFilterLevel(40);

        Snap cmbSnap = new Snap(cmb);
        Snap lmbSnap = new Snap(lmb);

        LoopFilter.loopFilterUVBlock(cmb, lmb, null, 0, KEY_FRAME);

        cmbSnap.assertPlaneChanged(cmb, U, "chroma U");
        cmbSnap.assertPlaneChanged(cmb, V, "chroma V");
        lmbSnap.assertPlaneChanged(lmb, U, "chroma U of the neighbour");
        lmbSnap.assertPlaneChanged(lmb, V, "chroma V of the neighbour");
        cmbSnap.assertPlaneUnchanged(cmb, Y1, "luma");
        cmbSnap.assertPlaneUnchanged(cmb, Y2, "Y2");
        assertTrue(edgeGap(cmb, lmb, U) < 20, "The chroma edge must be smoothed");
        assertTrue(edgeGap(cmb, lmb, V) < 20, "The chroma edge must be smoothed");
    }

    @Test
    void uvBlockDoesNothingWhenFilterLevelIsZero() {
        MacroBlock cmb = macroBlock(100);
        MacroBlock lmb = macroBlock(120);
        cmb.setFilterLevel(0);

        Snap cmbSnap = new Snap(cmb);
        Snap lmbSnap = new Snap(lmb);

        LoopFilter.loopFilterUVBlock(cmb, lmb, null, 0, KEY_FRAME);

        cmbSnap.assertUnchanged(cmb, "current macro block");
        lmbSnap.assertUnchanged(lmb, "left macro block");
    }

    @Test
    void uvBlockDoesNothingForStrongEdges() {
        MacroBlock cmb = macroBlock(20);
        MacroBlock lmb = macroBlock(220);
        cmb.setFilterLevel(40);

        Snap cmbSnap = new Snap(cmb);
        Snap lmbSnap = new Snap(lmb);

        LoopFilter.loopFilterUVBlock(cmb, lmb, null, 0, KEY_FRAME);

        cmbSnap.assertUnchanged(cmb, "current macro block");
        lmbSnap.assertUnchanged(lmb, "left macro block");
    }

    @Test
    void uvBlockFiltersInternalEdgesWithoutNeighbours() {
        MacroBlock cmb = macroBlock(100);
        for (int i = 0; i < 2; i++) {
            cmb.getSubBlock(U, 0, i).setDest(uniform(120));
            cmb.getSubBlock(V, 0, i).setDest(uniform(120));
        }
        cmb.setFilterLevel(40);

        LoopFilter.loopFilterUVBlock(cmb, null, null, 0, INTER_FRAME);

        for (int i = 0; i < 2; i++) {
            for (SubBlock.Plane plane : new SubBlock.Plane[] {U, V}) {
                int[][] p = cmb.getSubBlock(plane, 0, i).getDest();
                int[][] q = cmb.getSubBlock(plane, 1, i).getDest();
                assertTrue(p[3][0] < 120, plane + " internal edge must be filtered from the left: " + p[3][0]);
                assertTrue(q[0][0] > 100, plane + " internal edge must be filtered from the right: " + q[0][0]);
            }
        }
    }

    // --- simple filter ---------------------------------------------------------

    @Test
    void simpleBlockSmoothsLumaEdgeOnly() {
        MacroBlock cmb = macroBlock(100);
        MacroBlock lmb = macroBlock(120);
        cmb.setFilterLevel(40);

        Snap cmbSnap = new Snap(cmb);
        Snap lmbSnap = new Snap(lmb);

        LoopFilter.loopFilterSimpleBlock(cmb, lmb, null, 0);

        cmbSnap.assertPlaneChanged(cmb, Y1, "luma");
        lmbSnap.assertPlaneChanged(lmb, Y1, "luma of the neighbour");
        cmbSnap.assertPlaneUnchanged(cmb, U, "chroma U");
        cmbSnap.assertPlaneUnchanged(cmb, V, "chroma V");
        assertTrue(edgeGap(cmb, lmb, Y1) < 20, "The macro block edge must be smoothed");
    }

    @Test
    void simpleBlockDoesNothingWhenFilterLevelIsZero() {
        MacroBlock cmb = macroBlock(100);
        MacroBlock lmb = macroBlock(120);
        cmb.setFilterLevel(0);

        Snap cmbSnap = new Snap(cmb);
        Snap lmbSnap = new Snap(lmb);

        LoopFilter.loopFilterSimpleBlock(cmb, lmb, null, 0);

        cmbSnap.assertUnchanged(cmb, "current macro block");
        lmbSnap.assertUnchanged(lmb, "left macro block");
    }

    @Test
    void simpleBlockDoesNothingForStrongEdges() {
        MacroBlock cmb = macroBlock(20);
        MacroBlock lmb = macroBlock(220);
        cmb.setFilterLevel(40);

        Snap cmbSnap = new Snap(cmb);
        Snap lmbSnap = new Snap(lmb);

        LoopFilter.loopFilterSimpleBlock(cmb, lmb, null, 0);

        cmbSnap.assertUnchanged(cmb, "current macro block");
        lmbSnap.assertUnchanged(lmb, "left macro block");
    }

    @Test
    void simpleBlockSharpnessLevelReducesFiltering() {
        // P1 - P0 == 30 is tolerated for sharpness 0, but not for sharpness 7
        MacroBlock cmbSoft = macroBlock(100);
        MacroBlock lmbSoft = macroBlock(100);
        setRows(lmbSoft.getSubBlock(Y1, 3, 0), 130, 130, 130, 100);
        cmbSoft.setFilterLevel(40);
        LoopFilter.loopFilterSimpleBlock(cmbSoft, lmbSoft, 7 - 7);

        assertNotEquals(100, lmbSoft.getSubBlock(Y1, 3, 0).getDest()[3][0],
                "With sharpness 0 the strong interior difference is tolerated");

        MacroBlock cmbSharp = macroBlock(100);
        MacroBlock lmbSharp = macroBlock(100);
        setRows(lmbSharp.getSubBlock(Y1, 3, 0), 130, 130, 130, 100);
        cmbSharp.setFilterLevel(40);
        Snap cmbSnap = new Snap(cmbSharp);
        Snap lmbSnap = new Snap(lmbSharp);

        LoopFilter.loopFilterSimpleBlock(cmbSharp, lmbSharp, 7);

        cmbSnap.assertUnchanged(cmbSharp, "current macro block (sharpness 7)");
        lmbSnap.assertUnchanged(lmbSharp, "left macro block (sharpness 7)");
    }

    // --- robustness ------------------------------------------------------------

    @Test
    void extremePixelValuesStayInRange() {
        MacroBlock cmb = macroBlock(0);
        MacroBlock lmb = macroBlock(255);
        MacroBlock tmb = macroBlock(255);
        cmb.setFilterLevel(63);

        LoopFilter.loopFilterBlock(cmb, lmb, tmb, KEY_FRAME, false, 0);
        LoopFilter.loopFilterBlock(cmb, lmb, tmb, KEY_FRAME, true, 0);

        assertPlaneInRange(cmb);
        assertPlaneInRange(lmb);
        assertPlaneInRange(tmb);
    }

    @Test
    void filteringWithoutNeighboursDoesNotFail() {
        MacroBlock cmb = macroBlock(100);
        cmb.setFilterLevel(20);

        LoopFilter.loopFilterBlock(cmb, null, null, INTER_FRAME, false, 0);
        LoopFilter.loopFilterBlock(cmb, null, null, INTER_FRAME, true, 0);

        assertPlaneInRange(cmb);
    }

    @Test
    void allFrameTypesSharpnessAndLevelsKeepPixelsInRange() {
        for (int frameType : new int[] {KEY_FRAME, INTER_FRAME}) {
            for (int sharpness = 0; sharpness <= 7; sharpness++) {
                for (int level : new int[] {1, 14, 15, 19, 20, 39, 40, 63}) {
                    MacroBlock cmb = macroBlock(100);
                    MacroBlock lmb = macroBlock(115);
                    MacroBlock tmb = macroBlock(85);
                    cmb.setFilterLevel(level);

                    LoopFilter.loopFilterYBlock(cmb, lmb, tmb, sharpness, frameType);
                    LoopFilter.loopFilterUVBlock(cmb, lmb, tmb, sharpness, frameType);
                    LoopFilter.loopFilterSimpleBlock(cmb, lmb, tmb, sharpness);

                    assertPlaneInRange(cmb);
                    assertPlaneInRange(lmb);
                    assertPlaneInRange(tmb);
                }
            }
        }
    }

    // --- helpers ---------------------------------------------------------------

    private static MacroBlock macroBlock(int value) {
        MacroBlock mb = new MacroBlock(0, 0, true);
        for (int x = 0; x < 4; x++) {
            for (int y = 0; y < 4; y++) {
                mb.getSubBlock(Y1, x, y).setDest(uniform(value));
            }
        }
        for (int x = 0; x < 2; x++) {
            for (int y = 0; y < 2; y++) {
                mb.getSubBlock(U, x, y).setDest(uniform(value));
                mb.getSubBlock(V, x, y).setDest(uniform(value));
            }
        }
        mb.getY2SubBlock().setDest(uniform(value));
        return mb;
    }

    private static int[][] uniform(int value) {
        return rows(value, value, value, value);
    }

    private static int[][] rows(int r0, int r1, int r2, int r3) {
        return new int[][] {
                {r0, r0, r0, r0},
                {r1, r1, r1, r1},
                {r2, r2, r2, r2},
                {r3, r3, r3, r3}
        };
    }

    private static void setRows(SubBlock sb, int r0, int r1, int r2, int r3) {
        sb.setDest(rows(r0, r1, r2, r3));
    }

    private static int[][] copy(int[][] source) {
        int[][] result = new int[source.length][];
        for (int i = 0; i < source.length; i++) {
            result[i] = source[i].clone();
        }
        return result;
    }

    private static void setSkipInnerLoopFilter(MacroBlock mb, boolean value) throws Exception {
        Field field = MacroBlock.class.getDeclaredField("skipInnerLoopFilter");
        field.setAccessible(true);
        field.setBoolean(mb, value);
    }

    private static int planeColumns(SubBlock.Plane plane) {
        switch (plane) {
            case Y1:
                return 4;
            case U:
            case V:
                return 2;
            default:
                return 1;
        }
    }

    private static SubBlock subBlock(MacroBlock mb, SubBlock.Plane plane, int x, int y) {
        return plane == Y2 ? mb.getY2SubBlock() : mb.getSubBlock(plane, x, y);
    }

    /** Largest |P0 - Q0| over the left macro block edge of the given plane. */
    private static int edgeGap(MacroBlock cmb, MacroBlock lmb, SubBlock.Plane plane) {
        int last = planeColumns(plane) - 1;
        int gap = 0;
        for (int y = 0; y < planeColumns(plane); y++) {
            int p0 = subBlock(lmb, plane, last, y).getDest()[3][0];
            int q0 = subBlock(cmb, plane, 0, y).getDest()[0][0];
            gap = Math.max(gap, Math.abs(p0 - q0));
        }
        return gap;
    }

    private static void assertPixels(String message, int[][] expected, int[][] actual) {
        for (int r = 0; r < expected.length; r++) {
            for (int c = 0; c < expected[r].length; c++) {
                assertEquals(expected[r][c], actual[r][c], message + " at [" + r + "][" + c + "]");
            }
        }
    }

    private static void assertPlaneInRange(MacroBlock mb) {
        for (SubBlock.Plane plane : new SubBlock.Plane[] {Y1, U, V, Y2}) {
            int columns = planeColumns(plane);
            for (int x = 0; x < columns; x++) {
                for (int y = 0; y < columns; y++) {
                    int[][] dest = subBlock(mb, plane, x, y).getDest();
                    for (int[] row : dest) {
                        for (int value : row) {
                            assertTrue(value >= 0 && value <= 255,
                                    plane + "[" + x + "," + y + "] out of range: " + value);
                        }
                    }
                }
            }
        }
    }

    /** Snapshot of all sample arrays of a macro block, used for change detection. */
    private static final class Snap {
        private final int[][][][] planes = new int[SubBlock.Plane.values().length][][][];

        Snap(MacroBlock mb) {
            for (SubBlock.Plane plane : SubBlock.Plane.values()) {
                int columns = planeColumns(plane);
                int[][][] blocks = new int[columns * columns][][];
                for (int x = 0; x < columns; x++) {
                    for (int y = 0; y < columns; y++) {
                        blocks[x * columns + y] = copy(subBlock(mb, plane, x, y).getDest());
                    }
                }
                planes[plane.ordinal()] = blocks;
            }
        }

        void assertUnchanged(MacroBlock mb, String description) {
            for (SubBlock.Plane plane : SubBlock.Plane.values()) {
                assertPlaneUnchanged(mb, plane, description);
            }
        }

        void assertPlaneUnchanged(MacroBlock mb, SubBlock.Plane plane, String description) {
            assertEquals(0, differences(mb, plane), description + ": " + plane + " plane must not be modified");
        }

        void assertPlaneChanged(MacroBlock mb, SubBlock.Plane plane, String description) {
            int differences = differences(mb, plane);
            assertTrue(differences > 0, description + ": " + plane + " plane was expected to be modified");
        }

        private int differences(MacroBlock mb, SubBlock.Plane plane) {
            int columns = planeColumns(plane);
            int[][][] before = planes[plane.ordinal()];
            int changed = 0;
            for (int x = 0; x < columns; x++) {
                for (int y = 0; y < columns; y++) {
                    int[][] expected = before[x * columns + y];
                    int[][] actual = subBlock(mb, plane, x, y).getDest();
                    for (int r = 0; r < expected.length; r++) {
                        for (int c = 0; c < expected[r].length; c++) {
                            if (expected[r][c] != actual[r][c]) {
                                changed++;
                            }
                        }
                    }
                }
            }
            return changed;
        }
    }
}
