        cmbSnap.assertUnchanged(cmb, "current macro block");
        lmbSnap.assertUnchanged(lmb, "left macro block");
    }

    @Test
    void sharpnessLevelLimitsInteriorDifferenceTolerance() {
        // P3 == P2 == P1 == 130, P0 == Q0..Q3 == 100: interior difference of 30
        MacroBlock cmbSoft = macroBlock(100);
        MacroBlock lmbSoft = macroBlock(100);
        setRows(lmbSoft.getSubBlock(Y1, 3, 0), 130, 130, 130, 100);
        cmbSoft.setFilterLevel(40);

        LoopFilter.loopFilterYBlock(cmbSoft, lmbSoft, null, 0, KEY_FRAME);

        assertNotEquals(100, lmbSoft.getSubBlock(Y1, 3, 0).getDest()[3][0],
                "With sharpness 0 the interior difference of 30 is tolerated, filtering must happen");

        MacroBlock cmbSharp = macroBlock(100);
        MacroBlock lmbSharp = macroBlock(100);
        setRows(lmbSharp.getSubBlock(Y1, 3, 0), 130, 130, 130, 100);
        cmbSharp.setFilterLevel(40);
        Snap cmbSharpSnap = new Snap(cmbSharp);
        Snap lmbSharpSnap = new Snap(lmbSharp);

        LoopFilter.loopFilterYBlock(cmbSharp, lmbSharp, null, 7, KEY_FRAME);

        cmbSharpSnap.assertUnchanged(cmbSharp, "current macro block (sharpness 7)");
        lmbSharpSnap.assertUnchanged(lmbSharp, "left macro block (sharpness 7)");
    }

    @Test
    void yBlockHighEdgeVarianceUsesOuterTapsOnly() {
        // |P1 - P0| == 14 exceeds the key frame HEV threshold of 2, but stays
        // within the interior limit of 40.
        MacroBlock cmbHev = macroBlock(100);
        MacroBlock lmbHev = macroBlock(100);
        setRows(lmbHev.getSubBlock(Y1, 3, 0), 114, 114, 114, 100);
        cmbHev.setFilterLevel(40);

        LoopFilter.loopFilterYBlock(cmbHev, lmbHev, null, 0, KEY_FRAME);

        int[][] pHev = lmbHev.getSubBlock(Y1, 3, 0).getDest();
        int[][] qHev = cmbHev.getSubBlock(Y1, 0, 0).getDest();
        assertEquals(114, pHev[1][0], "High edge variance: P2 must stay untouched");
        assertEquals(100, qHev[2][0], "High edge variance: Q2 must stay untouched");
        assertNotEquals(100, pHev[3][0], "Pixels adjacent to the edge are always adjusted");

        // No high edge variance, but a clear step: the wide 7 tap filter runs
        MacroBlock cmbWide = macroBlock(100);
        MacroBlock lmbWide = macroBlock(120);
        cmbWide.setFilterLevel(40);

        LoopFilter.loopFilterYBlock(cmbWide, lmbWide, null, 0, KEY_FRAME);

        int[][] pWide = lmbWide.getSubBlock(Y1, 3, 0).getDest();
        int[][] qWide = cmbWide.getSubBlock(Y1, 0, 0).getDest();
        assertNotEquals(120, pWide[1][0], "Low edge variance: P2 is adjusted by the wide filter");
        assertNotEquals(100, qWide[2][0], "Low edge variance: Q2 is adjusted by the wide filter");
    }

    @Test
    void yBlockFiltersInternalSubBlockEdgesWithoutNeighbours() {
        MacroBlock cmb = macroBlock(100);
        for (int b = 0; b < 4; b++) {
            cmb.getSubBlock(Y1, 0, b).setDest(uniform(120));
        }
        cmb.setFilterLevel(40);

        LoopFilter.loopFilterYBlock(cmb, null, null, 0, KEY_FRAME);

        for (int b = 0; b < 4; b++) {
            int[][] p = cmb.getSubBlock(Y1, 0, b).getDest();
            int[][] q = cmb.getSubBlock(Y1, 1, b).getDest();
            assertTrue(p[3][0] < 120, "Internal edge must be filtered from the left: " + p[3][0]);
            assertTrue(q[0][0] > 100, "Internal edge must be filtered from the right: " + q[0][0]);
            assertPixels("sub block column 2 is untouched", uniform(100), cmb.getSubBlock(Y1, 2, b).getDest());
        }
    }

    @Test
    void yBlockSkipsInternalEdgesWhenSkipInnerLoopFilterIsSet() throws Exception {
        MacroBlock cmb = macroBlock(100);
        for (int b = 0; b < 4; b++) {
            cmb.getSubBlock(Y1, 0, b).setDest(uniform(120));
        }
        cmb.setFilterLevel(40);
        setSkipInnerLoopFilter(cmb, true);
        assertTrue(cmb.isSkip_inner_lf(), "Precondition: inner loop filter is skipped");

        Snap snap = new Snap(cmb);
        LoopFilter.loopFilterYBlock(cmb, null, null, 0, KEY_FRAME);

        snap.assertUnchanged(cmb, "macro block with skip_inner_lf set");
    }

    // --- chroma (U/V) filtering -----------------------------------------------

    @Test
    void uvBlockFiltersBothChromaPlanes() {
        MacroBlock cmb = macroBlock(100);
        MacroBlock lmb = macroBlock(120);
        cmb.setFilterLevel(40);

        Snap cmbSnap = new Snap(cmb);
        Snap lmbSnap = new Snap(lmb);

        LoopFilter.loopFilterUVBlock(cmb, lmb, null, 0, KEY_FRAME);

        cmbSnap.assertPlaneChanged(cmb, U, "chroma U");
        cmbSnap.assertPlaneChanged(cmb, V, "chroma V");
        lmbSnap.assertPlaneChanged(lmb, U, "chroma U of the neighbour");
        lmbSnap.assertPlaneChanged(lmb, V, "chroma V of the neighbour");
        cmbSnap.assertPlaneUnchanged(cmb, Y1, "luma");
        cmbSnap.assertPlaneUnchanged(cmb, Y2, "Y2");
        assertTrue(edgeGap(cmb, lmb, U) < 20, "The chroma edge must be smoothed");
        assertTrue(edgeGap(cmb, lmb, V) < 20, "The chroma edge must be smoothed");
    }

    @Test
    void uvBlockDoesNothingWhenFilterLevelIsZero() {
        MacroBlock cmb = macroBlock(100);
        MacroBlock lmb = macroBlock(120);
        cmb.setFilterLevel(0);

        Snap cmbSnap = new Snap(cmb);
        Snap lmbSnap = new Snap(lmb);

        LoopFilter.loopFilterUVBlock(cmb, lmb, null, 0, KEY_FRAME);

        cmbSnap.assertUnchanged(cmb, "current macro block");
        lmbSnap.assertUnchanged(lmb, "left macro block");
    }

    @Test
    void uvBlockDoesNothingForStrongEdges() {
        MacroBlock cmb = macroBlock(20);
        MacroBlock lmb = macroBlock(220);
        cmb.setFilterLevel(40);

        Snap cmbSnap = new Snap(cmb);
        Snap lmbSnap = new Snap(lmb);

        LoopFilter.loopFilterUVBlock(cmb, lmb, null, 0, KEY_FRAME);

        cmbSnap.assertUnchanged(cmb, "current macro block");
        lmbSnap.assertUnchanged(lmb, "left macro block");
    }

    @Test
    void uvBlockFiltersInternalEdgesWithoutNeighbours() {
        MacroBlock cmb = macroBlock(100);
        for (int i = 0; i < 2; i++) {
            cmb.getSubBlock(U, 0, i).setDest(uniform(120));
            cmb.getSubBlock(V, 0, i).setDest(uniform(120));
        }
        cmb.setFilterLevel(40);

        LoopFilter.loopFilterUVBlock(cmb, null, null, 0, INTER_FRAME);

        for (int i = 0; i < 2; i++) {
