    @Test
    void exposesRgbImageMetadataTypesAndExactPixels() throws IOException {
        byte[] rgb = rgbBytes(
                0xFF0000, 0x00FF00, 0x0000FF,
                0xFFFFFF, 0x000000, 0xFFFF00);
        byte[] tiff = new TiffBuilder()
                .startImage(3, 2, 8, 3, TIFFBaseline.PHOTOMETRIC_RGB)
                .stripData(rgb)
                .endImage()
                .build();

        reader = createReader(tiff);

        assertEquals(1, reader.getNumImages(false));
        assertEquals(1, reader.getNumImages(true));
        assertEquals(3, reader.getWidth(0));
        assertEquals(2, reader.getHeight(0));
        assertTrue(reader.canReadRaster());
        assertFalse(reader.isImageTiled(0));
        assertEquals(3, reader.getTileWidth(0));
        assertEquals(2, reader.getTileHeight(0));

        ImageTypeSpecifier rawType = reader.getRawImageType(0);
        assertEquals(3, rawType.getNumBands());
        assertEquals(8, rawType.getBitsPerBand(0));
        assertEquals(DataBuffer.TYPE_BYTE, rawType.getSampleModel().getTransferType());
        assertEquals(ColorSpace.TYPE_RGB, rawType.getColorModel().getColorSpace().getType());

        Iterator<ImageTypeSpecifier> imageTypes = reader.getImageTypes(0);
        assertTrue(imageTypes.hasNext());
        ImageTypeSpecifier firstType = imageTypes.next();
        assertEquals(BufferedImage.TYPE_3BYTE_BGR, firstType.getBufferedImageType());
        assertTrue(imageTypes.hasNext());
        assertEquals(rawType, imageTypes.next());
        assertFalse(imageTypes.hasNext());

        BufferedImage image = reader.read(0, null);
        assertEquals(3, image.getWidth());
        assertEquals(2, image.getHeight());
        assertEquals(BufferedImage.TYPE_3BYTE_BGR, image.getType());
        assertRgb(image, 0, 0, 0xFF0000);
        assertRgb(image, 1, 0, 0x00FF00);
        assertRgb(image, 2, 0, 0x0000FF);
        assertRgb(image, 0, 1, 0xFFFFFF);
        assertRgb(image, 1, 1, 0x000000);
        assertRgb(image, 2, 1, 0xFFFF00);

        Raster raster = reader.readRaster(0, null);
        assertNotNull(raster);
        assertEquals(3, raster.getWidth());
        assertEquals(2, raster.getHeight());
        assertEquals(3, raster.getNumBands());
        // The default RGB destination stores BGR bytes in the raster bands.
        assertArrayEquals(new int[]{0, 255, 0}, raster.getPixel(0, 0, (int[]) null));
    }

    @Test
    void readsMultipleStripsWhileSelectingSourceRegionAndSubsampling() throws IOException {
        int[] colors = {
                0xFF0000, 0x00FF00, 0x0000FF, 0xFFFFFF,
                0x000000, 0xFFFF00, 0x00FFFF, 0xFF00FF,
                0x800000, 0x008000, 0x000080, 0x808080,
                0x400000, 0x004000, 0x000040, 0xC0C0C0
        };
        byte[] rows = rgbBytes(colors);
        byte[] tiff = new TiffBuilder()
                .startImage(4, 4, 8, 3, TIFFBaseline.PHOTOMETRIC_RGB)
                .tag(TIFF.TAG_ROWS_PER_STRIP, TIFF.TYPE_LONG, 1)
                .stripData(Arrays.copyOfRange(rows, 0, 12), Arrays.copyOfRange(rows, 12, 24),
                        Arrays.copyOfRange(rows, 24, 36), Arrays.copyOfRange(rows, 36, 48))
                .endImage()
                .build();

        reader = createReader(tiff);

        ImageReadParam regionParam = reader.getDefaultReadParam();
        regionParam.setSourceRegion(new Rectangle(1, 1, 2, 2));
        BufferedImage region = reader.read(0, regionParam);
        assertEquals(2, region.getWidth());
        assertEquals(2, region.getHeight());
        assertRgb(region, 0, 0, colors[5]);
        assertRgb(region, 1, 0, colors[6]);
        assertRgb(region, 0, 1, colors[9]);
        assertRgb(region, 1, 1, colors[10]);

        ImageReadParam subsamplingParam = reader.getDefaultReadParam();
        subsamplingParam.setSourceSubsampling(2, 2, 0, 0);
        BufferedImage subsampled = reader.read(0, subsamplingParam);
        assertEquals(2, subsampled.getWidth());
        assertEquals(2, subsampled.getHeight());
        assertRgb(subsampled, 0, 0, colors[0]);
        assertRgb(subsampled, 1, 0, colors[2]);
        assertRgb(subsampled, 0, 1, colors[8]);
        assertRgb(subsampled, 1, 1, colors[10]);
    }

    @Test
    void writesIntoExplicitDestinationAtRequestedOffsetAndLeavesOtherPixelsUntouched() throws IOException {
        int[] colors = {
                0xFF0000, 0x00FF00, 0x0000FF, 0xFFFFFF,
                0x000000, 0xFFFF00, 0x00FFFF, 0xFF00FF,
                0x800000, 0x008000, 0x000080, 0x808080,
                0x400000, 0x004000, 0x000040, 0xC0C0C0
        };
        byte[] tiff = new TiffBuilder()
                .startImage(4, 4, 8, 3, TIFFBaseline.PHOTOMETRIC_RGB)
                .stripData(rgbBytes(colors))
                .endImage()
                .build();

        reader = createReader(tiff);

        BufferedImage destination = new BufferedImage(5, 5, BufferedImage.TYPE_3BYTE_BGR);
        Graphics2D graphics = destination.createGraphics();
        try {
            graphics.setColor(Color.MAGENTA);
            graphics.fillRect(0, 0, destination.getWidth(), destination.getHeight());
        }
        finally {
            graphics.dispose();
        }

        ImageReadParam param = reader.getDefaultReadParam();
        param.setDestination(destination);
        param.setSourceRegion(new Rectangle(1, 1, 2, 2));
        param.setDestinationOffset(new Point(1, 1));

        BufferedImage result = reader.read(0, param);

        assertSame(destination, result);
        assertRgb(result, 0, 0, 0xFF00FF);
        assertRgb(result, 1, 1, colors[5]);
        assertRgb(result, 2, 1, colors[6]);
        assertRgb(result, 1, 2, colors[9]);
        assertRgb(result, 2, 2, colors[10]);
        assertRgb(result, 4, 4, 0xFF00FF);
    }

    @Test
