        colorMap[0] = 0xFFFF;             // index 0: red
        colorMap[256 + 1] = 0xFFFF;       // index 1: green
        colorMap[2 * 256 + 2] = 0xFFFF;   // index 2: blue

        byte[] tiff = new TiffBuilder()
                .startImage(3, 1, 8, 1, TIFFBaseline.PHOTOMETRIC_PALETTE)
