                .endImage()
                .build();

        reader = createReader(tiff);

        ImageTypeSpecifier rawType = reader.getRawImageType(0);
        assertEquals(1, rawType.getNumBands());
        assertEquals(8, rawType.getBitsPerBand(0));
        assertTrue(rawType.getColorModel() instanceof IndexColorModel);

        BufferedImage image = reader.read(0, null);
        assertEquals(BufferedImage.TYPE_BYTE_INDEXED, image.getType());
        assertRgb(image, 0, 0, 0xFF0000);
        assertRgb(image, 1, 0, 0x00FF00);
        assertRgb(image, 2, 0, 0x0000FF);
    }

    @Test
    void readsSixteenBitGraySamplesInBigEndianInput() throws IOException {
        TiffBuilder builder = new TiffBuilder(ByteOrder.BIG_ENDIAN);
        builder.startImage(2, 2, 16, 1, TIFFBaseline.PHOTOMETRIC_BLACK_IS_ZERO)
                .stripData(shorts(ByteOrder.BIG_ENDIAN, 0x0000, 0x1234, 0xABCD, 0xFFFF))
                .endImage();
        byte[] tiff = builder.build();

        reader = createReader(tiff);

        ImageTypeSpecifier rawType = reader.getRawImageType(0);
        assertEquals(1, rawType.getNumBands());
        assertEquals(16, rawType.getBitsPerBand(0));
        assertEquals(ColorSpace.TYPE_GRAY, rawType.getColorModel().getColorSpace().getType());
        assertEquals(DataBuffer.TYPE_USHORT, rawType.getSampleModel().getTransferType());

        BufferedImage image = reader.read(0, null);
        assertEquals(2, image.getWidth());
        assertEquals(2, image.getHeight());
        assertEquals(0x0000, image.getRaster().getSample(0, 0, 0));
        assertEquals(0x1234, image.getRaster().getSample(1, 0, 0));
        assertEquals(0xABCD, image.getRaster().getSample(0, 1, 0));
        assertEquals(0xFFFF, image.getRaster().getSample(1, 1, 0));

        IIOMetadata streamMetadata = reader.getStreamMetadata();
        IIOMetadataNode streamTree = (IIOMetadataNode) streamMetadata.getAsTree(TIFFStreamMetadata.SUN_NATIVE_STREAM_METADATA_FORMAT_NAME);
        assertEquals(TIFFStreamMetadata.SUN_NATIVE_STREAM_METADATA_FORMAT_NAME, streamTree.getNodeName());
        Node byteOrder = streamTree.getFirstChild();
        assertEquals("ByteOrder", byteOrder.getNodeName());
        assertEquals("BIG_ENDIAN", ((IIOMetadataNode) byteOrder).getAttribute("value"));
    }

    @Test
    void readsTilesAndRejectsOutOfBoundsTiles() throws IOException {
        byte[] firstTile = rgbBytes(
                0xFF0000, 0x00FF00,
                0x0000FF, 0xFFFFFF);
        byte[] secondTilePadded = rgbBytes(
                0xFFFF00, 0x000000,
                0x00FFFF, 0x000000); // second column and second row are padding
        byte[] tiff = new TiffBuilder()
                .startImage(3, 2, 8, 3, TIFFBaseline.PHOTOMETRIC_RGB)
                .removeTag(TIFF.TAG_ROWS_PER_STRIP)
                .tag(TIFF.TAG_TILE_WIDTH, TIFF.TYPE_LONG, 2)
                .tag(TIFF.TAG_TILE_HEIGTH, TIFF.TYPE_LONG, 2)
                .tileData(firstTile, secondTilePadded)
                .endImage()
                .build();

        reader = createReader(tiff);

        assertTrue(reader.isImageTiled(0));
        assertEquals(2, reader.getTileWidth(0));
        assertEquals(2, reader.getTileHeight(0));

        BufferedImage first = reader.readTile(0, 0, 0);
        assertEquals(2, first.getWidth());
        assertEquals(2, first.getHeight());
        assertRgb(first, 0, 0, 0xFF0000);
        assertRgb(first, 1, 0, 0x00FF00);
        assertRgb(first, 0, 1, 0x0000FF);
        assertRgb(first, 1, 1, 0xFFFFFF);

        BufferedImage second = reader.readTile(0, 1, 0);
        assertEquals(1, second.getWidth());
        assertEquals(2, second.getHeight());
        assertRgb(second, 0, 0, 0xFFFF00);
        assertRgb(second, 0, 1, 0x00FFFF);

        Raster secondRaster = reader.readTileRaster(0, 1, 0);
        assertEquals(1, secondRaster.getWidth());
        assertEquals(2, secondRaster.getHeight());
        assertArrayEquals(new int[]{0, 255, 255}, secondRaster.getPixel(0, 0, (int[]) null));

        assertThrows(IllegalArgumentException.class, () -> reader.readTile(0, 2, 0));
    }

    @Test
    void exposesMultipleIfdsAndTheirMetadata() throws IOException {
        TiffBuilder builder = new TiffBuilder();
        builder.startImage(1, 1, 8, 1, TIFFBaseline.PHOTOMETRIC_BLACK_IS_ZERO)
                .stripData(new byte[]{(byte) 0x80})
                .endImage();
        builder.startImage(2, 1, 8, 3, TIFFBaseline.PHOTOMETRIC_RGB)
                .stripData(rgbBytes(0x123456, 0xABCDEF))
                .endImage();
        byte[] tiff = builder.build();

        reader = createReader(tiff);

        assertEquals(2, reader.getNumImages(false));
        assertEquals(1, reader.getWidth(0));
        assertEquals(2, reader.getWidth(1));
        assertEquals(1, reader.getHeight(1));

        BufferedImage second = reader.read(1, null);
        assertRgb(second, 0, 0, 0x123456);
        assertRgb(second, 1, 0, 0xABCDEF);

        IIOMetadata imageMetadata = reader.getImageMetadata(0);
        IIOMetadataNode imageTree = (IIOMetadataNode) imageMetadata.getAsTree(TIFFImageMetadataFormat.SUN_NATIVE_IMAGE_METADATA_FORMAT_NAME);
        assertEquals(TIFFImageMetadataFormat.SUN_NATIVE_IMAGE_METADATA_FORMAT_NAME, imageTree.getNodeName());
        Node ifdNode = imageTree.getFirstChild();
        assertEquals("TIFFIFD", ifdNode.getNodeName());
        assertTrue(ifdNode.getChildNodes().getLength() >= 6);

        IIOMetadata streamMetadata = reader.getStreamMetadata();
        IIOMetadataNode streamTree = (IIOMetadataNode) streamMetadata.getAsTree(TIFFStreamMetadata.SUN_NATIVE_STREAM_METADATA_FORMAT_NAME);
        assertEquals("LITTLE_ENDIAN", ((IIOMetadataNode) streamTree.getFirstChild()).getAttribute("value"));

        assertThrows(IndexOutOfBoundsException.class, () -> reader.getImageMetadata(2));
    }

    @Test
    void fallsBackToGuessedPhotometricInterpretationAndEmitsWarning() throws IOException {
        byte[] tiff = new TiffBuilder()
                .startImage(1, 1, 8, 3, TIFFBaseline.PHOTOMETRIC_RGB)
                .removeTag(TIFF.TAG_PHOTOMETRIC_INTERPRETATION)
