    @Test
    void rejectsUnsupportedCompressionAndInvalidImageDescriptions() throws IOException {
        byte[] unsupported = new TiffBuilder()
                .startImage(1, 1, 8, 1, TIFFBaseline.PHOTOMETRIC_BLACK_IS_ZERO)
                .tag(TIFF.TAG_COMPRESSION, TIFF.TYPE_SHORT, TIFFCustom.COMPRESSION_NEXT)
                .stripData(new byte[]{0})
                .endImage()
                .build();
        reader = createReader(unsupported);
        IIOException compressionException = assertThrows(IIOException.class, () -> reader.read(0, null));
        assertTrue(compressionException.getMessage().contains("Unsupported TIFF Compression"));

        byte[] variableBits = new TiffBuilder()
                .startImage(1, 1, 8, 3, TIFFBaseline.PHOTOMETRIC_RGB)
                .tag(TIFF.TAG_BITS_PER_SAMPLE, TIFF.TYPE_SHORT, 8, 8, 16)
                .stripData(rgbBytes(0x112233))
