                .startImage(1, 1, 8, 1, TIFFBaseline.PHOTOMETRIC_BLACK_IS_ZERO)
                .tag(TIFF.TAG_PHOTOMETRIC_INTERPRETATION, TIFF.TYPE_SHORT, 999)
