    @Test
    void rejectsImplausiblyLargeImageBeforeAllocation() throws IOException {
        byte[] tiff = new TiffBuilder()
                .startImage(100_000, 100_000, 8, 3, TIFFBaseline.PHOTOMETRIC_RGB)
                .stripData(rgbBytes(0xFF0000))
                .endImage()
                .build();

        reader = createReader(tiff);
        IIOException exception = assertThrows(IIOException.class, () -> reader.read(0, null));
        assertTrue(exception.getMessage().contains("exceeding"));
