    @Test
    void enforcesInputAndImageBounds() throws IOException {
        reader = new TIFFImageReader(new TIFFImageReaderSpi());
        assertThrows(IllegalStateException.class, () -> reader.getNumImages(false));

        byte[] tiff = new TiffBuilder()
                .startImage(1, 1, 8, 1, TIFFBaseline.PHOTOMETRIC_BLACK_IS_ZERO)
                .stripData(new byte[]{0})
                .endImage()
                .build();
        reader.setInput(new ByteArrayImageInputStream(tiff));

        assertThrows(IndexOutOfBoundsException.class, () -> reader.getWidth(1));
        assertThrows(IndexOutOfBoundsException.class, () -> reader.read(-1, null));
