        for (int y = 0; y < 4; y++) {
            for (int x = 0; x < 4; x++) {
                if (ySubBlocks[x][y] == sb) {
                    return x;
                }
            }
        }
    }
    else if (sb.getPlane() == SubBlock.Plane.U) {
        for (int y = 0; y < 2; y++) {
            for (int x = 0; x < 2; x++) {
                if (uSubBlocks[x][y] == sb) {
                    return x;
                }
            }
        }
    }
    else if (sb.getPlane() == SubBlock.Plane.V) {
        for (int y = 0; y < 2; y++) {
            for (int x = 0; x < 2; x++) {
                if (vSubBlocks[x][y] == sb) {
                    return x;
                }
            }
        }
