public void predictUV(VP8Frame frame) {
    MacroBlock aboveMb = frame.getMacroBlock(x, y - 1);
    MacroBlock leftMb = frame.getMacroBlock(x - 1, y);

    switch (this.uvMode) {
        case Globals.DC_PRED:
            // System.out.println("UV DC_PRED");

            boolean up_available = false;
            boolean left_available = false;
            int Uaverage = 0;
            int Vaverage = 0;
            int expected_udc;
            int expected_vdc;
            if (x > 0) {
                left_available = true;
            }
            if (y > 0) {
                up_available = true;
            }
            if (up_available || left_available) {
                if (up_available) {
                    for (int j = 0; j < 2; j++) {
                        SubBlock usb = aboveMb.getUSubBlock(j, 1);
                        SubBlock vsb = aboveMb.getVSubBlock(j, 1);
                        for (int i = 0; i < 4; i++) {
                            Uaverage += usb.getRecon()[i][3];
                            Vaverage += vsb.getRecon()[i][3];
                        }
                    }
                }

                if (left_available) {
                    for (int j = 0; j < 2; j++) {
                        SubBlock usb = leftMb.getUSubBlock(1, j);
                        SubBlock vsb = leftMb.getVSubBlock(1, j);
                        for (int i = 0; i < 4; i++) {
                            Uaverage += usb.getRecon()[3][i];
                            Vaverage += vsb.getRecon()[3][i];
                        }
                    }
                }

                int shift = 2;
                if (up_available) {
                    shift++;
                }
                if (left_available) {
                    shift++;
                }

                expected_udc = (Uaverage + (1 << (shift - 1))) >> shift;
                expected_vdc = (Vaverage + (1 << (shift - 1))) >> shift;
            }
            else {
                expected_udc = 128;
                expected_vdc = 128;
            }

            int[][] ufill = new int[4][4];
            for (int y = 0; y < 4; y++) {
                for (int x = 0; x < 4; x++) {
                    ufill[x][y] = expected_udc;
                }
            }

            int[][] vfill = new int[4][4];
            for (int y = 0; y < 4; y++) {
                for (int x = 0; x < 4; x++) {
                    vfill[x][y] = expected_vdc;
                }
            }

            for (int y = 0; y < 2; y++) {
                for (int x = 0; x < 2; x++) {
                    SubBlock usb = uSubBlocks[x][y];
                    SubBlock vsb = vSubBlocks[x][y];
                    usb.setPredict(ufill);
                    vsb.setPredict(vfill);
                }
            }

            break;
        case Globals.V_PRED:
            // System.out.println("UV V_PRED");

            SubBlock[] aboveUSb = new SubBlock[2];
            SubBlock[] aboveVSb = new SubBlock[2];
            for (int x = 0; x < 2; x++) {
                aboveUSb[x] = aboveMb.getUSubBlock(x, 1);
                aboveVSb[x] = aboveMb.getVSubBlock(x, 1);
            }

            for (int y = 0; y < 2; y++) {
                for (int x = 0; x < 2; x++) {
                    SubBlock usb = uSubBlocks[y][x];
                    SubBlock vsb = vSubBlocks[y][x];
                    int[][] ublock = new int[4][4];
                    int[][] vblock = new int[4][4];
                    for (int j = 0; j < 4; j++) {
                        for (int i = 0; i < 4; i++) {
                            ublock[j][i] = aboveUSb[y]
                                    .getMacroBlockReconPredict(Globals.V_PRED)[j][3];
                            vblock[j][i] = aboveVSb[y]
                                    .getMacroBlockReconPredict(Globals.V_PRED)[j][3];
                        }
                    }
                    usb.setPredict(ublock);
                    vsb.setPredict(vblock);
                }
            }

            break;

        case Globals.H_PRED:
            // System.out.println("UV H_PRED");

            SubBlock[] leftUSb = new SubBlock[2];
            SubBlock[] leftVSb = new SubBlock[2];
            for (int x = 0; x < 2; x++) {
                leftUSb[x] = leftMb.getUSubBlock(1, x);
                leftVSb[x] = leftMb.getVSubBlock(1, x);
            }

            for (int y = 0; y < 2; y++) {
                for (int x = 0; x < 2; x++) {
                    SubBlock usb = uSubBlocks[x][y];
                    SubBlock vsb = vSubBlocks[x][y];

                        SubBlock vsb = vSubBlocks[x][y];
                        int[][] ublock = new int[4][4];
                        int[][] vblock = new int[4][4];
                        for (int j = 0; j < 4; j++) {
                            for (int i = 0; i < 4; i++) {
                                ublock[i][j] = leftUSb[y]
                                        .getMacroBlockReconPredict(Globals.H_PRED)[3][j];
                                vblock[i][j] = leftVSb[y]
                                        .getMacroBlockReconPredict(Globals.H_PRED)[3][j];
                            }
                        }
                        usb.setPredict(ublock);
                        vsb.setPredict(vblock);
                    }
                }

                break;
            case Globals.TM_PRED:
                // TODO:
                // System.out.println("UV TM_PRED MB");
                boolean aboveRowAvailableUV = this.y > 0;
                MacroBlock ALMb = frame.getMacroBlock(x - 1, y - 1);
                SubBlock ALUSb = ALMb.getUSubBlock(1, 1);
                int alu = ALUSb.getReconAboveLeft(aboveRowAvailableUV)[3][3];
                SubBlock ALVSb = ALMb.getVSubBlock(1, 1);
                int alv = ALVSb.getReconAboveLeft(aboveRowAvailableUV)[3][3];

                aboveUSb = new SubBlock[2];
                leftUSb = new SubBlock[2];
                aboveVSb = new SubBlock[2];
                leftVSb = new SubBlock[2];
                for (int x = 0; x < 2; x++) {
                    aboveUSb[x] = aboveMb.getUSubBlock(x, 1);
                    leftUSb[x] = leftMb.getUSubBlock(1, x);
                    aboveVSb[x] = aboveMb.getVSubBlock(x, 1);
                    leftVSb[x] = leftMb.getVSubBlock(1, x);
                }

                for (int b = 0; b < 2; b++) {
                    for (int a = 0; a < 4; a++) {
                        for (int d = 0; d < 2; d++) {
                            for (int c = 0; c < 4; c++) {

                                int upred = leftUSb[b].getReconLeft()[3][a]
                                        + aboveUSb[d].getReconAbove()[c][3] - alu;
                                upred = Globals.clamp(upred, 255);
                                uSubBlocks[d][b].setPixel(c, a, upred);

                                int vpred = leftVSb[b].getReconLeft()[3][a]
                                        + aboveVSb[d].getReconAbove()[c][3] - alv;
                                vpred = Globals.clamp(vpred, 255);
                                vSubBlocks[d][b].setPixel(c, a, vpred);
                            }
                        }
                    }
                }

                break;
            default:
                // TODO: FixME!
                throw new AssertionError("TODO predict_mb_uv: " + this.yMode);
        }
    }

    public void predictY(VP8Frame frame) {
        MacroBlock aboveMb = frame.getMacroBlock(x, y - 1);
        MacroBlock leftMb = frame.getMacroBlock(x - 1, y);

        switch (this.yMode) {
            case Globals.DC_PRED:
                // System.out.println("DC_PRED");
                boolean up_available = false;
                boolean left_available = false;

                int average = 0;
                int expected_dc;
                if (x > 0) {
                    left_available = true;
                }
                if (y > 0) {
                    up_available = true;
                }

                if (up_available || left_available) {
                    if (up_available) {
                        for (int j = 0; j < 4; j++) {
                            SubBlock sb = aboveMb.getYSubBlock(j, 3);
                            for (int i = 0; i < 4; i++) {
                                average += sb.getRecon()[i][3];
                            }
                        }
                    }

                    if (left_available) {
                        for (int j = 0; j < 4; j++) {
                            SubBlock sb = leftMb.getYSubBlock(3, j);
                            for (int i = 0; i < 4; i++) {
                                average += sb.getRecon()[3][i];
                            }
                        }
                    }

                    int shift = 3;
                    if (up_available) {
                        shift++;
                    }
                    if (left_available) {
                        shift++;
                    }

                    expected_dc = (average + (1 << (shift - 1))) >> shift;
                }
                else {
                    expected_dc = 128;
                }

                int[][] fill = new int[4][4];
                for (int y = 0; y < 4; y++) {
                    for (int x = 0; x < 4; x++) {
                        fill[x][y] = expected_dc;
                    }
                }
                for (int y = 0; y < 4; y++) {
                    for (int x = 0; x < 4; x++) {
                        SubBlock sb = ySubBlocks[x][y];
                        sb.setPredict(fill);
                    }
                }

                break;
            case Globals.V_PRED:
                // System.out.println("V_PRED");

                SubBlock[] aboveYSb = new SubBlock[4];
                for (int x = 0; x < 4; x++) {
                    aboveYSb[x] = aboveMb.getYSubBlock(x, 3);
                }

                for (int y = 0; y < 4; y++) {
                    for (int x = 0; x < 4; x++) {
                        SubBlock sb = ySubBlocks[x][y];
                        int[][] block = new int[4][4];
                        for (int j = 0; j < 4; j++) {
                            for (int i = 0; i < 4; i++) {
                                block[i][j] = aboveYSb[x].getReconPredict(
                                        Globals.B_VE_PRED, false)[i][3];
                            }
                        }
                        sb.setPredict(block);
                    }
                }

                break;

            case Globals.H_PRED:
                // System.out.println("H_PRED");

                SubBlock[] leftYSb = new SubBlock[4];
                for (int x = 0; x < 4; x++) {
                    leftYSb[x] = leftMb.getYSubBlock(3, x);
                }

                for (int y = 0; y < 4; y++) {
                    for (int x = 0; x < 4; x++) {
                        SubBlock sb = ySubBlocks[x][y];
                        int[][] block = new int[4][4];
                        for (int j = 0; j < 4; j++) {
                            for (int i = 0; i < 4; i++) {
                                block[i][j] = leftYSb[y].getReconPredict(
                                        Globals.B_DC_PRED, true)[3][j];
                            }
                        }
                        sb.setPredict(block);
                    }
                }

//                 SubBlock[] leftUSb = new SubBlock[2];
//                 for (int x = 0; x < 2; x++) {
//                     leftUSb[x] = leftMb.getYSubBlock(1, x);
//                 }

                break;
            case Globals.TM_PRED:
                // System.out.println("TM_PRED MB");
                boolean aboveRowAvailableY = this.y > 0;
                MacroBlock ALMb = frame.getMacroBlock(x - 1, y - 1);
                SubBlock ALSb = ALMb.getYSubBlock(3, 3);
                int al = ALSb.getReconAboveLeft(aboveRowAvailableY)[3][3];

                aboveYSb = new SubBlock[4];
                leftYSb = new SubBlock[4];
                for (int x = 0; x < 4; x++) {
                    aboveYSb[x] = aboveMb.getYSubBlock(x, 3);
                }
                for (int x = 0; x < 4; x++) {
                    leftYSb[x] = leftMb.getYSubBlock(3, x);
                }
//                 fill = new int[4][4];

                for (int b = 0; b < 4; b++) {
                    for (int a = 0; a < 4; a++) {

                        for (int d = 0; d < 4; d++) {
                            for (int c = 0; c < 4; c++) {
                                int pred = leftYSb[b].getReconLeft()[3][a]
                                        + aboveYSb[d].getReconAbove()[c][3] - al;

                                ySubBlocks[d][b].setPixel(c, a,
                                        Globals.clamp(pred, 255));
                            }
                        }
                    }
                }

                break;
            default:
                System.out.println("TODO predict_mb_y: " + this.yMode);
                System.exit(0);
        }
    }

    public void recon_mb() {
        for (int j = 0; j < 4; j++) {
            for (int i = 0; i < 4; i++) {
                SubBlock sb = ySubBlocks[i][j];
                sb.reconstruct();
            }
        }

        for (int j = 0; j < 2; j++) {
            for (int i = 0; i < 2; i++) {
                SubBlock sb = uSubBlocks[i][j];
                sb.reconstruct();
            }
        }
        for (int j = 0; j < 2; j++) {
            for (int i = 0; i < 2; i++) {
                SubBlock sb = vSubBlocks[i][j];
                sb.reconstruct();
            }
        }
    }

