            for (int i = 0; i < 4; i++) {
                expected_dc += above[i];
                expected_dc += left[i];
            }
            expected_dc = (expected_dc + 4) >> 3;

            for (int y = 0; y < 4; y++) {
                for (int x = 0; x < 4; x++) {
                    p[x][y] = expected_dc;
