}

public void reconstruct() {
    SubBlock sb = this;

    int r, c;
    int[][] p = sb.getPredict(1, false);

    int[][] dest = new int[4][4];
    int[][] diff = sb.getDiff();

    for (r = 0; r < 4; r++) {
        for (c = 0; c < 4; c++) {
            int a = diff[r][c] + p[r][c];

            if (a < 0) {
                a = 0;
            }

            if (a > 255) {
                a = 255;
            }

            dest[r][c] = a;
        }
    }

    sb.setDest(dest);
    if (!this.getMacroBlock().isKeepDebugInfo()) {
        sb.diff = null;
        sb.predict = null;
        sb.tokens = null;
    }
}

