        }
        assertEquals(2, mb.uSubBlocks.length);
        assertEquals(2, mb.uSubBlocks[0].length);
        assertEquals(2, mb.vSubBlocks.length);
        assertEquals(2, mb.vSubBlocks[0].length);

        for (int y = 0; y < 4; y++) {
            for (int x = 0; x < 4; x++) {
                SubBlock sb = mb.getYSubBlock(x, y);
                assertNotNull(sb);
                assertSame(mb, sb.getMacroBlock());
                assertEquals(SubBlock.Plane.Y1, sb.getPlane());
                assertFalse(sb.hasNoZeroToken());
                assertFalse(sb.hasRecon());
                assertFalse(sb.isDest());

                if (x == 0) {
                    assertNull(sb.getLeft());
                }
                else {
                    assertSame(mb.getYSubBlock(x - 1, y), sb.getLeft());
                }
                if (y == 0) {
                    assertNull(sb.getAbove());
                }
