        byte[] b = new byte[bytes.length];
        for (int i = 0; i < bytes.length; i++) b[i] = (byte) bytes[i];
        return new BoolDecoder(new MemoryCacheImageInputStream(new ByteArrayInputStream(b)), 0);
    }

    static int[][][][] uniform(int v) {
        int[][][][] p = new int[4][8][3][11];
        for (int a = 0; a < p.length; a++)
            for (int b = 0; b < p[a].length; b++)
                for (int c = 0; c < p[a][b].length; c++)
                    Arrays.fill(p[a][b][c], v);
        return p;
    }

    static void run(String label, int[][][][] probs, int[] stream, boolean withY2, int type, int ilc) throws Exception {
        BoolDecoder bc = decoder(stream);
        MacroBlock mb = new MacroBlock(1, 1, false);
