package com.twelvemonkeys.imageio.plugins.webp.vp8;

import org.junit.jupiter.api.Test;

import javax.imageio.stream.ImageInputStream;
import javax.imageio.stream.MemoryCacheImageInputStream;
import java.io.ByteArrayInputStream;
import java.io.IOException;
import java.lang.reflect.Field;
import java.util.Arrays;

import static org.junit.jupiter.api.Assertions.assertArrayEquals;
import static org.junit.jupiter.api.Assertions.assertEquals;
import static org.junit.jupiter.api.Assertions.assertFalse;
import static org.junit.jupiter.api.Assertions.assertNotNull;
import static org.junit.jupiter.api.Assertions.assertSame;
import static org.junit.jupiter.api.Assertions.assertTrue;

/**
 * Behavioural tests for {@link SubBlock}, the 4x4 coefficient block of the
 * WebP (VP8) decoder.
 * <p>
 * The tests use real collaborators ({@link MacroBlock}, {@link VP8Frame},
 * {@link SegmentQuants}, {@link BoolDecoder}) and drive the bit level
 * {@link SubBlock#decodeSubBlock} entry point with hand made bit streams, so
 * that every expected value can be derived from the VP8 specification
 * (RFC 6386) instead of from a live decoder run.
 */
class SubBlockTests {

    /**
     * A stream of {@code 0xFF} bytes makes every boolean decision of the
     * arithmetic decoder come out as a one, which for the coefficient tree of
     * RFC 6386, section 13.2 means: "not EOB", "not zero", "not one",
     * "not two", ... up to category 6, plus eleven extra magnitude bits and a
     * sign bit.
     */
    private static final int ALL_ONES_TOKEN = -(67 + 2047);

    /**
     * A stream of {@code 0x00} bytes makes every boolean decision come out as a
     * zero, so the very first decision of the coefficient tree is end-of-block.
     */
    private static final int[] ZERO_TOKENS = new int[16];

    // ------------------------------------------------------------------
    // Helpers
    // ------------------------------------------------------------------

    private static SubBlock newSubBlock(SubBlock.Plane plane) {
        return new SubBlock(new MacroBlock(1, 1, false), null, null, plane);
    }

    private static SubBlock newSubBlock(MacroBlock macroBlock, SubBlock.Plane plane) {
        return new SubBlock(macroBlock, null, null, plane);
    }

    private static int[][] filled(int value) {
        int[][] block = new int[4][4];
        for (int[] row : block) {
            Arrays.fill(row, value);
        }
        return block;
    }

    /** A block with all sixteen samples distinct: 10 * row + column + 1. */
    private static int[][] uniqueBlock() {
        int[][] block = new int[4][4];
        for (int r = 0; r < 4; r++) {
            for (int c = 0; c < 4; c++) {
                block[r][c] = 10 * r + c + 1;
            }
        }
        return block;
    }

    private static void assertFilled(int expected, int[][] block) {
        assertNotNull(block, "block");
        for (int r = 0; r < 4; r++) {
            for (int c = 0; c < 4; c++) {
                assertEquals(expected, block[r][c], "sample [" + r + "][" + c + "]");
            }
        }
    }

    private static void assertNotFilled(int unexpected, int[][] block) {
        boolean allSame = true;
        for (int r = 0; r < 4 && allSame; r++) {
            for (int c = 0; c < 4 && allSame; c++) {
                allSame = block[r][c] == unexpected;
            }
        }
        assertFalse(allSame, "expected block with varying samples, got a constant " + unexpected);
    }

    private static BoolDecoder decoder(int fill, int length) throws IOException {
        int[] bytes = new int[length];
        Arrays.fill(bytes, fill);
        return decoder(bytes);
    }

    private static BoolDecoder decoder(int[] bytes) throws IOException {
        byte[] data = new byte[bytes.length];
        for (int i = 0; i < bytes.length; i++) {
            data[i] = (byte) bytes[i];
        }
        ImageInputStream stream = new MemoryCacheImageInputStream(new ByteArrayInputStream(data));
        return new BoolDecoder(stream, 0);
    }

    /** Coefficient probabilities with the same value for every node. */
    private static int[][][][] uniformCoefProbs(int value) {
        int[][][][] probs = new int[4][8][3][11];
        for (int[][][] plane : probs) {
            for (int[][] band : plane) {
                for (int[] context : band) {
                    Arrays.fill(context, value);
                }
            }
        }
        return probs;
    }

    private static SegmentQuants quants(int qIndex, int y1DcDelta, int uvDcDelta, int uvAcDelta) {
        SegmentQuants quants = new SegmentQuants();
        for (SegmentQuant quant : quants.getSegQuants()) {
            quant.setQindex(qIndex);
            quant.setY1dc(y1DcDelta);
            quant.setUvdc_delta_q(uvDcDelta);
            quant.setUvac_delta_q(uvAcDelta);
        }
        return quants;
    }

    private static SegmentQuants quantsPerSegment(int... qIndexes) {
        SegmentQuants quants = new SegmentQuants();
        SegmentQuant[] segments = quants.getSegQuants();
        for (int i = 0; i < segments.length; i++) {
            segments[i].setQindex(qIndexes[Math.min(i, qIndexes.length - 1)]);
            segments[i].setY1dc(0);
        }
        return quants;
    }

    /**
     * Creates a real {@link VP8Frame} whose segment quantizers have been set up
     * without decoding a whole frame (the frame parses the quantizers as part of
     * {@code decode()}, which needs a complete bitstream).
     */
    private static VP8Frame frameWithQuants(SegmentQuants quants) throws Exception {
        ImageInputStream stream = new MemoryCacheImageInputStream(new ByteArrayInputStream(new byte[0]));
        VP8Frame frame = new VP8Frame(stream, false);

        Field field = VP8Frame.class.getDeclaredField("segmentQuants");
        field.setAccessible(true);
        field.set(frame, quants);

        return frame;
    }

