        subBlock.drawDebug();
        subBlock.getDest()[3][3] = 7;

        assertArrayEquals(uniqueBlock(), subBlock.getRecon(),
                "reconstruction snapshot must not see post filtering changes");
        assertEquals(7, subBlock.getDest()[3][3], "destination was modified");
