@Test
void planeToTypeSelectsCoefficientProbabilityTable() {
    // Y2 always has its own table, Y1 has one when a Y2 block is present
    assertEquals(1, SubBlock.planeToType(SubBlock.Plane.Y2, true), "Y2 with Y2 block");
    assertEquals(1, SubBlock.planeToType(SubBlock.Plane.Y2, false), "Y2 without Y2 block");

    assertEquals(0, SubBlock.planeToType(SubBlock.Plane.Y1, true), "Y1 with Y2 block");
    assertEquals(3, SubBlock.planeToType(SubBlock.Plane.Y1, false), "Y1 without Y2 block");

    assertEquals(3, SubBlock.planeToType(SubBlock.Plane.Y1, false), "Y1 without Y2 block");

    // Both chroma planes share the same table
    assertEquals(2, SubBlock.planeToType(SubBlock.Plane.U, true), "U");
    assertEquals(2, SubBlock.planeToType(SubBlock.Plane.U, false), "U");
    assertEquals(2, SubBlock.planeToType(SubBlock.Plane.V, true), "V");
    assertEquals(2, SubBlock.planeToType(SubBlock.Plane.V, false), "V");
}

