@Test
void setDestPublishesBlockAndSnapshotsUnfilteredReconstruction() {
    SubBlock subBlock = newSubBlock(SubBlock.Plane.Y1);
    int[][] dest = uniqueBlock();

    subBlock.setDest(dest);

    assertTrue(subBlock.isDest(), "destination published");
    assertSame(dest, subBlock.getDest(), "destination is stored as is");
    assertTrue(subBlock.hasRecon(), "reconstruction snapshot taken");

    int[][] recon = subBlock.getRecon();
    assertArrayEquals(uniqueBlock(), recon, "snapshot equals the reconstruction");
    assertNotSame(dest, recon, "snapshot must be an independent copy");
    assertSame(recon, subBlock.getRecon(), "snapshot is stable");
}

@Test
void reconstructionSnapshotSurvivesLaterFilteringOfTheDestination() {
    SubBlock subBlock = newSubBlock(SubBlock.Plane.Y1);
    subBlock.setDest(uniqueBlock());

    // The loop filter runs on the destination, never on the snapshot
    subBlock.drawDebug();
    subBlock.getDest()[3][3] = 7;

    assertArrayEquals(uniqueBlock(), subBlock.getRecon(),
            "reconstruction snapshot must not see post filtering changes");
    assertEquals(7, subBlock.getDest()[3][3], "destination was modified");
}

@Test
void setPixelCreatesDestinationOnDemand() {
    SubBlock subBlock = newSubBlock(SubBlock.Plane.U);
    assertFalse(subBlock.isDest());

    subBlock.setPixel(2, 3, 42);

    assertTrue(subBlock.isDest(), "destination created");
    int[][] dest = subBlock.getDest();
    assertEquals(42, dest[2][3], "written sample");
    assertFilledExcept(0, dest, 2, 3);

    subBlock.setPixel(0, 0, 255);
    assertEquals(255, subBlock.getDest()[0][0], "second sample");
    assertEquals(42, subBlock.getDest()[2][3], "first sample kept");
}

private static void assertFilledExcept(int expected, int[][] block, int skipX, int skipY) {
    for (int x = 0; x < 4; x++) {
        for (int y = 0; y < 4; y++) {
            if (x != skipX || y != skipY) {
                assertEquals(expected, block[x][y], "sample [" + x + "][" + y + "]");
            }
        }
    }
}

