        int sourceYSubsampling = param != null ? param.getSourceYSubsampling() : 1;

        for (int row = 0; row < macroBlockRows; row++) {
            if (parts > 1) {
                tokenBoolDecoder = tokenBoolDecoders.get(ibc);
                tokenBoolDecoder.seek();

                ibc++;
                if (ibc == parts) {
                    ibc = 0;
                }
            }

