        int[] offs = new int[masks.length];

        for (int i = 0; i < masks.length; i++) {
            int mask = masks[i];
            int off = 0;

            // TODO: FixMe! This only works for standard 8 bit masks (0xFF)
            if (mask != 0) {
                while ((mask & 0xFF) == 0) {
                    mask >>>= 8;
                    off++;
                }
            }

            offs[i] = off;
        }

        return offs;
    }
}
