import java.util.*;

public class Probe {
  static byte[] frame(String p) throws Exception {
    byte[] b = Files.readAllBytes(Paths.get(p));
    ByteBuffer bb = ByteBuffer.wrap(b).order(ByteOrder.LITTLE_ENDIAN);
    if (b[0]!='R'||b[1]!='I'||b[2]!='F'||b[3]!='F') throw new IllegalArgumentException("not riff");
    int off=12;
    while(off+8<=b.length){
      String id=new String(b, off, 4, "US-ASCII");
      int len=bb.getInt(off+4);
      System.out.println("chunk "+id+" off="+(off+8)+" len="+len);
      if(id.equals("VP8 ")) return Arrays.copyOfRange(b, off+8, off+8+len);
      off += 8+len+(len&1);
    }
    throw new IllegalArgumentException("no VP8");
  }
  static class L implements javax.imageio.event.IIOReadProgressListener {
