    WritableRaster r=img.getRaster().createWritableChild(0,0,16,16,0,0,null);
    boolean ok=vf.decode(r,null);
    System.out.println("ok="+ok+" type="+vf.getFrameType()+" w="+vf.getWidth()+" h="+vf.getHeight()+" mb="+vf.getMacroBlockCols()+"x"+vf.getMacroBlockRows()+" q="+vf.getQIndex()+" sharp="+vf.getSharpnessLevel()+" progress="+l.vals);
    for(int y=0;y<Math.min(16,vf.getHeight());y++){StringBuilder sb=new StringBuilder();for(int x=0;x<Math.min(16,vf.getWidth());x++){int[] pixel=r.getPixel(x,y,(int[])null);sb.append(String.format("%02x%02x%02x ",pixel[0],pixel[1],pixel[2]));}System.out.println(sb);}
    SegmentQuants sq=vf.getSegmentQuants();
    for(int i=0;i<4;i++){SegmentQuant q=sq.getSegQuants()[i];System.out.println("seg"+i+" q="+q.getQindex()+" filter="+q.getFilterStrength()+" y1dc="+q.getY1dc()+" y1ac="+q.getY1ac()+" y2dc="+q.getY2dc()+" y2ac="+q.getY2ac_delta_q()+" uvdc="+q.getUvdc_delta_q()+" uvac="+q.getUvac_delta_q());}
    System.out.println("mbstr="+vf.getMacroBlockDebugString(0,0,0,0));
    for(String m:new String[]{"Diff","Predict","UBuffer","UDiffBuffer","UPredBuffer","VBuffer","VDiffBuffer","VPredBuffer","YBuffer","YDiffBuffer","YPredBuffer"}){
      java.lang.reflect.Method mm=VP8Frame.class.getMethod("getDebugImage"+m);
      BufferedImage bi=(BufferedImage)mm.invoke(vf);
      System.out.println(m+" %dx%d type=%d sample0=%08x sampleLast=%08x".replace("%dx%d","").replace("%d","").replace("%08x","")+ (bi==null?"null":bi.getWidth()+"x"+bi.getHeight()+" type="+bi.getType()+" p0="+Integer.toHexString(bi.getRGB(0,0))+" plast="+Integer.toHexString(bi.getRGB(bi.getWidth()-1,bi.getHeight()-1))));
    }
    BoolDecoder bd=vf.getTokenBoolDecoder();
    System.out.println("token="+(bd!=null));
    System.out.println("coef dims="+Arrays.deepToString(dims(vf.getCoefProbs())));
  }
  static int[] dims(Object o){ if(o instanceof int[]){return new int[]{((int[])o).length};} int n=java.lang.reflect.Array.getLength(o); int[] d=dims(java.lang.reflect.Array.get(o,0)); int[] res=new int[d.length+1]; res[0]=n; System.arraycopy(d,0,res,1,d.length); return res;}
  public static void main(String[] a)throws Exception{ for(String p:a) {System.out.println("=== "+p); probe(p);} }
}
