package com.twelvemonkeys.imageio.plugins.webp.vp8;

import org.junit.jupiter.api.Test;

import javax.imageio.ImageReadParam;
import javax.imageio.event.IIOReadProgressListener;
import javax.imageio.stream.ImageInputStream;
import javax.imageio.stream.MemoryCacheImageInputStream;
import java.awt.Rectangle;
import java.awt.image.BufferedImage;
import java.io.ByteArrayInputStream;
import java.io.ByteArrayOutputStream;
import java.io.EOFException;
import java.io.IOException;
import java.io.InputStream;
import java.util.ArrayList;
import java.util.List;

import static org.junit.jupiter.api.Assertions.assertEquals;
import static org.junit.jupiter.api.Assertions.assertFalse;
import static org.junit.jupiter.api.Assertions.assertNotNull;
import static org.junit.jupiter.api.Assertions.assertSame;
import static org.junit.jupiter.api.Assertions.assertThrows;
import static org.junit.jupiter.api.Assertions.assertTrue;

class VP8FrameTests {
    private static final String RESOURCE_ROOT = "/webp/";
    private static final float FLOAT_DELTA = 0.0001f;

    @Test
    void constructorInitializesUnparsedFrameStateAndDefaultCoefficientProbabilities() throws IOException {
        VP8Frame frame = new VP8Frame(stream(new byte[0]), false);

        assertEquals(0, frame.getFrameType());
        assertEquals(0, frame.getWidth());
        assertEquals(0, frame.getHeight());
        assertEquals(0, frame.getMacroBlockCols());
        assertEquals(0, frame.getMacroBlockRows());
        assertEquals(0, frame.getSharpnessLevel());

        int[][][][] probabilities = frame.getCoefProbs();
        assertEquals(4, probabilities.length);
        assertEquals(8, probabilities[0].length);
        assertEquals(3, probabilities[0][0].length);
        assertEquals(11, probabilities[0][0][0].length);
        assertEquals(128, probabilities[0][0][0][0]);
        assertEquals(253, probabilities[1][0][0][0]);
    }

    @Test
    void decodeReturnsFalseForInterFrameWithoutReadingTheRestOfTheFrame() throws IOException {
        VP8Frame frame = new VP8Frame(stream(new byte[] {0x01}), false);
        RecordingProgressListener listener = new RecordingProgressListener();
        frame.setProgressListener(listener);

        BufferedImage destination = new BufferedImage(1, 1, BufferedImage.TYPE_3BYTE_BGR);

        assertFalse(frame.decode(destination.getRaster(), null));
        assertEquals(1, frame.getFrameType());
        assertEquals(0, frame.getWidth());
        assertEquals(0, frame.getHeight());
        assertEquals(0, frame.getMacroBlockCols());
        assertEquals(0, frame.getMacroBlockRows());
        assertTrue(listener.progress.isEmpty());
    }

    @Test
    void decodeLossyKeyFrameExposesDimensionsQuantizationAndDecodedPixel() throws IOException {
        DecodeResult result = decode("small_1x1.webp", 1, 1, null);
        VP8Frame frame = result.frame;

        assertTrue(result.decoded);
        assertEquals(0, frame.getFrameType());
        assertEquals(1, frame.getWidth());
        assertEquals(1, frame.getHeight());
        assertEquals(1, frame.getMacroBlockCols());
        assertEquals(1, frame.getMacroBlockRows());
        assertEquals(4, frame.getQIndex());
        assertEquals(0, frame.getSharpnessLevel());

        SegmentQuants quants = frame.getSegmentQuants();
        assertNotNull(quants);
        assertEquals(4, quants.getSegQuants().length);
        for (SegmentQuant quant : quants.getSegQuants()) {
            assertEquals(4, quant.getQindex());
            assertEquals(0, quant.getFilterStrength());
            assertEquals(8, quant.getY1dc());
            assertEquals(8, quant.getY1ac());
            assertEquals(16, quant.getY2dc());
            assertEquals(12, quant.getY2ac_delta_q());
            assertEquals(8, quant.getUvdc_delta_q());
            assertEquals(8, quant.getUvac_delta_q());
        }

        assertEquals(0x008800, result.image.getRGB(0, 0) & 0xFFFFFF);
        assertNotNull(frame.getTokenBoolDecoder());
        assertSame(frame.getTokenBoolDecoder(), frame.getTokenBoolDecoder());
    }

    @Test
    void decodeReportsProgressAfterEveryMacroBlockRow() throws IOException {
        VP8Frame frame = frame("bug3.webp");
        RecordingProgressListener listener = new RecordingProgressListener();
        frame.setProgressListener(listener);
        BufferedImage destination = new BufferedImage(95, 95, BufferedImage.TYPE_3BYTE_BGR);

        assertTrue(frame.decode(destination.getRaster(), null));
        assertEquals(6, frame.getMacroBlockCols());
        assertEquals(6, frame.getMacroBlockRows());
        assertEquals(6, listener.progress.size());

        for (int i = 0; i < listener.progress.size(); i++) {
            assertEquals((i + 1) * 100.0f / 6.0f, listener.progress.get(i), FLOAT_DELTA);
        }
        assertEquals(100.0f, listener.progress.get(listener.progress.size() - 1), 0.0f);
    }

    @Test
    void decodeHonorsSourceRegionIndependentOfMacroBlockBoundaries() throws IOException {
        DecodeResult full = decode("small_31x13.webp", 31, 13, null);
        Rectangle sourceRegion = new Rectangle(5, 3, 9, 7);
        ImageReadParam param = new ImageReadParam();
        param.setSourceRegion(sourceRegion);

        DecodeResult cropped = decode("small_31x13.webp", 9, 7, param);

        for (int y = 0; y < sourceRegion.height; y++) {
            for (int x = 0; x < sourceRegion.width; x++) {
                assertEquals(full.image.getRGB(sourceRegion.x + x, sourceRegion.y + y),
                        cropped.image.getRGB(x, y),
                        "pixel (" + x + ", " + y + ") differs from full-frame source region");
            }
        }
    }

    @Test
    void decodeHonorsSourceSubsamplingWithOddImageDimensions() throws IOException {
        DecodeResult full = decode("small_31x13.webp", 31, 13, null);

        ImageReadParam param = new ImageReadParam();
        param.setSourceRegion(new Rectangle(0, 0, 31, 13));
        param.setSourceSubsampling(2, 2, 0, 0);

        DecodeResult subsampled = decode("small_31x13.webp", 16, 7, param);

        for (int y = 0; y < subsampled.image.getHeight(); y++) {
            for (int x = 0; x < subsampled.image.getWidth(); x++) {
                assertEquals(full.image.getRGB(x * 2, y * 2), subsampled.image.getRGB(x, y),
                        "pixel (" + x + ", " + y + ") differs from sampled full-frame pixel");
            }
        }
    }

    @Test
    void decodeSegmentedKeyFrameExposesPerSegmentQuantizationAndSharpness() throws IOException {
        DecodeResult result = decode("segment02.webp", 160, 160, null);
        VP8Frame frame = result.frame;

        assertEquals(160, frame.getWidth());
        assertEquals(160, frame.getHeight());
        assertEquals(10, frame.getMacroBlockCols());
        assertEquals(10, frame.getMacroBlockRows());
        assertEquals(64, frame.getQIndex());
        assertEquals(7, frame.getSharpnessLevel());

        SegmentQuant[] quants = frame.getSegmentQuants().getSegQuants();
        assertEquals(4, quants.length);

        assertEquals(64, quants[0].getQindex());
        assertEquals(50, quants[0].getFilterStrength());
        assertEquals(78, quants[0].getY1ac());
        assertEquals(70, quants[0].getUvac_delta_q());

        assertEquals(23, quants[1].getQindex());
        assertEquals(13, quants[1].getFilterStrength());
        assertEquals(27, quants[1].getY1ac());
        assertEquals(23, quants[1].getUvac_delta_q());

        assertEquals(0, quants[2].getQindex());
        assertEquals(0, quants[2].getFilterStrength());
        assertEquals(4, quants[2].getY1ac());
        assertEquals(4, quants[2].getUvac_delta_q());

        assertEquals(0, quants[3].getQindex());
        assertEquals(0, quants[3].getFilterStrength());

        assertEquals(0x3B4021, result.image.getRGB(0, 0) & 0xFFFFFF);
    }

    @Test
    void macroBlockDebugStringDescribesMacroBlockAndSubBlocksAndRejectsOutOfRangeCoordinates() throws IOException {
        DecodeResult result = decode("small_1x1.webp", 1, 1, null);
        VP8Frame frame = result.frame;

        String debug = frame.getMacroBlockDebugString(0, 0, 0, 0);
        assertTrue(debug.contains("YMode: DC_PRED"));
        assertTrue(debug.contains("UVMode: DC_PRED"));
        assertTrue(debug.contains("SegmentID: 0"));
        assertTrue(debug.contains("SubBlock 0, 0"));
        assertTrue(debug.contains("    Y1"));
        assertTrue(debug.contains("    Y2"));
        assertTrue(debug.contains("    U"));
        assertTrue(debug.contains("    V"));

        assertTrue(frame.getMacroBlockDebugString(0, 0, 4, 0).contains("YMode: DC_PRED"));
        assertFalse(frame.getMacroBlockDebugString(0, 0, 4, 0).contains("SubBlock"));
        assertEquals("", frame.getMacroBlockDebugString(1, 0, 0, 0));
        assertEquals("", frame.getMacroBlockDebugString(0, 1, 0, 0));
    }

    @Test
    void decodeThrowsEofForTruncatedKeyFrameHeader() throws IOException {
        VP8Frame frame = new VP8Frame(stream(new byte[] {0x00}), false);
        BufferedImage destination = new BufferedImage(1, 1, BufferedImage.TYPE_3BYTE_BGR);

        assertThrows(EOFException.class, () -> frame.decode(destination.getRaster(), null));
    }

    private static DecodeResult decode(String resource, int width, int height, ImageReadParam param) throws IOException {
        VP8Frame frame = frame(resource);
        BufferedImage image = new BufferedImage(width, height, BufferedImage.TYPE_3BYTE_BGR);
        boolean decoded = frame.decode(image.getRaster(), param);
        return new DecodeResult(frame, image, decoded);
    }

    private static VP8Frame frame(String resource) throws IOException {
        return new VP8Frame(stream(vp8Chunk(readResource(resource))), false);
    }

    private static ImageInputStream stream(byte[] bytes) {
        return new MemoryCacheImageInputStream(new ByteArrayInputStream(bytes));
    }

    private static byte[] readResource(String resource) throws IOException {
        String path = RESOURCE_ROOT + resource;
        try (InputStream input = VP8FrameTests.class.getResourceAsStream(path)) {
            if (input == null) {
                throw new IOException("Missing test resource: " + path);
            }

            ByteArrayOutputStream output = new ByteArrayOutputStream();
            byte[] buffer = new byte[4096];
            int count;
            while ((count = input.read(buffer)) >= 0) {
                output.write(buffer, 0, count);
            }
            return output.toByteArray();
        }
    }

    private static byte[] vp8Chunk(byte[] webp) throws IOException {
        if (webp.length < 20
                || webp[0] != 'R' || webp[1] != 'I' || webp[2] != 'F' || webp[3] != 'F'
                || webp[8] != 'W' || webp[9] != 'E' || webp[10] != 'B' || webp[11] != 'P') {
            throw new IOException("Not a WebP RIFF container");
        }

        int offset = 12;
        while (offset + 8 <= webp.length) {
            int length = readLittleEndianInt(webp, offset + 4);
            if (length < 0 || offset + 8L + length > webp.length) {
                throw new IOException("Invalid WebP chunk length at offset " + offset);
            }

            if (webp[offset] == 'V' && webp[offset + 1] == 'P'
                    && webp[offset + 2] == '8' && webp[offset + 3] == ' ') {
                byte[] chunk = new byte[length];
                System.arraycopy(webp, offset + 8, chunk, 0, length);
                return chunk;
            }

            offset += 8 + length + (length & 1);
        }

        throw new IOException("WebP container has no VP8 chunk");
    }

    private static int readLittleEndianInt(byte[] data, int offset) {
        return (data[offset] & 0xFF)
                | (data[offset + 1] & 0xFF) << 8
                | (data[offset + 2] & 0xFF) << 16
                | (data[offset + 3] & 0xFF) << 24;
    }

    private static final class DecodeResult {
        final VP8Frame frame;
        final BufferedImage image;
        final boolean decoded;

        DecodeResult(VP8Frame frame, BufferedImage image, boolean decoded) {
            this.frame = frame;
            this.image = image;
            this.decoded = decoded;
        }
    }

    private static final class RecordingProgressListener implements IIOReadProgressListener {
        final List<Float> progress = new ArrayList<>();

        @Override
        public void sequenceStarted(javax.imageio.ImageReader source, int minIndex) {
        }

        @Override
        public void sequenceComplete(javax.imageio.ImageReader source) {
        }

        @Override
        public void imageStarted(javax.imageio.ImageReader source, int imageIndex) {
        }

        @Override
        public void imageProgress(javax.imageio.ImageReader source, float percentageDone) {
            progress.add(percentageDone);
        }

        @Override
        public void imageComplete(javax.imageio.ImageReader source) {
        }

        @Override
        public void thumbnailStarted(javax.imageio.ImageReader source, int imageIndex, int thumbnailIndex) {
        }

        @Override
        public void thumbnailProgress(javax.imageio.ImageReader source, float percentageDone) {
        }

        @Override
        public void thumbnailComplete(javax.imageio.ImageReader source) {
        }

        @Override
        public void readAborted(javax.imageio.ImageReader source) {
        }
    }
}
